-- San Andreas Law Reference - Database Schema
-- ================================================

CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE TABLE sections (
    id          VARCHAR(30) PRIMARY KEY,
    title       TEXT NOT NULL,
    icon        VARCHAR(10),
    group_name  VARCHAR(50),
    has_filters BOOLEAN DEFAULT false,
    sort_order  INT DEFAULT 0
);


CREATE TABLE articles (
    id             SERIAL PRIMARY KEY,
    section_id     VARCHAR(30) NOT NULL REFERENCES sections(id),
    group_name     TEXT,
    article        VARCHAR(50),
    stars          VARCHAR(20),
    name           TEXT,
    description    TEXT,
    full_desc      TEXT,
    punishment     TEXT,
    fine           TEXT,
    has_conviction BOOLEAN DEFAULT false,
    jurisdiction   VARCHAR(20),
    important      TEXT,
    created_at     TIMESTAMPTZ DEFAULT NOW(),
    updated_at     TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX idx_articles_section ON articles(section_id);
CREATE INDEX idx_articles_trgm_name   ON articles USING gin (name gin_trgm_ops);
CREATE INDEX idx_articles_trgm_desc   ON articles USING gin (description gin_trgm_ops);
CREATE INDEX idx_articles_trgm_article ON articles USING gin (article gin_trgm_ops);

CREATE TABLE info_items (
    id          SERIAL PRIMARY KEY,
    section_id  VARCHAR(30) NOT NULL REFERENCES sections(id),
    title       TEXT,
    number      TEXT,
    description TEXT,
    items       JSONB DEFAULT '[]',
    who_applies TEXT,
    created_at  TIMESTAMPTZ DEFAULT NOW(),
    updated_at  TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX idx_info_section ON info_items(section_id);
CREATE INDEX idx_info_trgm_title ON info_items USING gin (title gin_trgm_ops);
CREATE INDEX idx_info_items_gin   ON info_items USING gin (items);

CREATE VIEW search_all AS
    SELECT
        a.id,
        a.section_id,
        s.title AS section_title,
        'article' AS item_type,
        a.article AS code,
        a.name AS title,
        a.description,
        a.punishment,
        a.fine,
        a.has_conviction,
        a.stars,
        a.jurisdiction,
        a.important,
        NULL::jsonb AS items
    FROM articles a
    JOIN sections s ON s.id = a.section_id
    UNION ALL
    SELECT
        i.id,
        i.section_id,
        s.title AS section_title,
        'info' AS item_type,
        i.number AS code,
        i.title,
        i.description,
        NULL, NULL, NULL, NULL, NULL, NULL,
        i.items
    FROM info_items i
    JOIN sections s ON s.id = i.section_id;


Легкий вред здоровью — кратковременное расстройство здоровья до 21 дня. Средний вред — длительное расстройство от 21 до 30 дней либо стойкая утрата трудоспособности менее чем на 1/3.', '3 года лишения свободы', '15 000–90 000$', false, 'Смеш', 'При назначении штрафа судимости не возникает. Причинение вреда в состоянии аффекта квалифицируется по ч.3.');

Тяжкий вред здоровью — вред, опасный для жизни, либо повлекший потерю зрения, речи, слуха, потерю органа, прерывание беременности, психическое расстройство, неизгладимое обезображивание лица, либо стойкую утрату трудоспособности не менее чем на 1/3.', '4 года лишения свободы', NULL, true, 'Смеш', 'Сроки давности не применяются. Забвение не вправе назначать штраф.');

Аффект — сильное душевное волнение, возникшее внезапно под воздействием насилия, издевательства или тяжкого оскорбления со стороны потерпевшего.', '3 года лишения свободы', '20 000–40 000$', false, 'Смеш', NULL);

Убийство признаётся оконченным с момента смерти потерпевшего. Обязательна причинно-следственная связь между действиями виновного и наступлением смерти.', '4 года лишения свободы', NULL, true, 'Смеш', 'Сроки давности не применяются.');

Отличие от ч.1: отсутствие умысла на лишение жизни. Виновный либо самонадеянно рассчитывал предотвратить смерть, либо не предвидел, но должен был предвидеть возможность её наступления.', '3 года лишения свободы', NULL, false, 'Смеш', NULL);

Квалифицирующие признаки:
- убийство двух или более лиц
- убийство лица в связи с осуществлением им служебной деятельности
- совершённое с особой жестокостью
- совершённое общеопасным способом
- совершённое группой лиц
- из корыстных побуждений или по найму', '5 лет лишения свободы', NULL, true, 'Смеш', 'Сроки давности не применяются.');

Обязательное условие: у потерпевшего имелись реальные основания опасаться осуществления угрозы (учитываются обстановка, личность угрожающего, его поведение, наличие оружия и т.д.).', '3 года лишения свободы', '30 000–50 000$', false, 'Смеш', NULL);

Формы воспрепятствования: физическое воздействие, угрозы, создание помех, давление, изъятие документов/оборудования и т.п.', '3 года лишения свободы', '5 000–20 000$', false, 'Смеш', NULL);

Квалифицирующие признаки: совершённое группой лиц, с применением насилия, с использованием оружия, в отношении заведомо несовершеннолетнего, из корыстных побуждений.', '5 лет лишения свободы', NULL, true, 'Фед', 'Сроки давности не применяются. Только FIB.');

Отличие от похищения: при незаконном лишении свободы отсутствует факт перемещения потерпевшего.', '4 года лишения свободы', NULL, true, 'Смеш', NULL);

Рабский труд — выполнение работ лицом, которое не может отказаться от их выполнения в силу физического или психического принуждения, зависимости или иных обстоятельств.', '4 года лишения свободы', NULL, true, 'Смеш', NULL);

Торговля людьми — купля-продажа человека либо его вербовка, перевозка, передача, укрывательство в целях эксплуатации.', '4 года лишения свободы', NULL, true, 'Смеш', NULL);

Клевета — распространение ложных сведений, не соответствующих действительности, унижающих честь и достоинство либо подрывающих репутацию.', '2-3 года лишения свободы', '40 000–50 000$', false, 'Смеш', NULL);

Публичный характер — выступление перед аудиторией, размещение в общедоступных источниках.', '2-3 года лишения свободы', '50 000–60 000$', false, 'Смеш', NULL);

Использование служебного положения — доступ к информации, использование подчинённых, служебные полномочия для распространения клеветы.', '2-3 года лишения свободы', '50 000–60 000$', false, 'Смеш', NULL);

Опасное заболевание — ВИЧ, туберкулёз, гепатит, венерические болезни и иные заболевания, представляющие опасность для окружающих.', '2-3 года лишения свободы', '50 000–70 000$', false, 'Смеш', NULL);

Обвинение в особо тяжком преступлении влечёт наиболее серьёзные последствия для репутации потерпевшего.', '2-3 года лишения свободы', '50 000–80 000$', false, 'Смеш', NULL);

Беспомощное состояние — потерпевшая не могла понять характер совершаемых с ней действий или оказать сопротивление в силу физического или психического состояния.', '4 года лишения свободы', NULL, true, 'Рег', NULL);

Квалифицирующие признаки:
- совершённое группой лиц
- соединённое с угрозой убийством или причинением тяжкого вреда здоровью
- совершённое с особой жестокостью
- повлёкшее по неосторожности смерть потерпевшего', '4 года лишения свободы', NULL, true, 'Рег', NULL);

Способы понуждения: шантаж, угроза уничтожения имущества, использование материальной или иной зависимости потерпевшего.', '3 года лишения свободы', NULL, false, 'Рег', NULL);

Формы домогательства: словесные предложения сексуального характера, непрошеные прикосновения, обещания вознаграждения в обмен на сексуальные услуги, совершённые без согласия жертвы.', '3 года лишения свободы', NULL, false, 'Рег', NULL);

Формы воспрепятствования: подкуп, обман, принуждение, насилие, угроза насилия, уничтожение избирательных документов.', '5 лет лишения свободы', NULL, true, 'Смеш', NULL);

Цель — нарушение нормального функционирования Сената, препятствие осуществлению его конституционных полномочий.', '3 года лишения свободы', '20 000$', false, 'Смеш', NULL);

Способы совершения: незаконное проникновение, создание барьеров, дестабилизация электронных систем, иные действия, целью которых является нарушение хода заседания.', '3 года лишения свободы', NULL, false, 'Смеш', NULL);

Тайность хищения означает, что изъятие имущества происходит незаметно для потерпевшего и окружающих. Минимальная стоимость предмета хищения — 15 000$. Менее 15 000$ — административное нарушение.', '3 года лишения свободы', NULL, false, 'Смеш', NULL);

Взлом — повреждение запорных устройств, подбор ключей, использование отмычек или иных средств для преодоления преград.', '4 года лишения свободы', NULL, true, 'Смеш', NULL);

Обман — сообщение ложных сведений либо умолчание об истинных фактах. Злоупотребление доверием — использование доверительных отношений в корыстных целях.', '3 года лишения свободы', NULL, false, 'Смеш', NULL);

Угрозы: насилие, уничтожение или повреждение имущества, распространение позорящих сведений, разглашение тайны. Вымогательство считается оконченным с момента предъявления требования.', '3 года лишения свободы', NULL, false, 'Смеш', NULL);

Открытость означает, что виновный осознаёт, что его действия очевидны для потерпевшего или окружающих. Насилие при грабеже не применяется.', '3 года лишения свободы', NULL, false, 'Смеш', NULL);

Разбой считается оконченным с момента нападения независимо от того, удалось ли завладеть имуществом. Насилие должно быть опасным для жизни или здоровья в момент применения.', '4 года лишения свободы', NULL, true, 'Смеш', NULL);

Отличие угона от кражи: при угоне отсутствует корыстная цель на обращение ТС в свою пользу. ТС возвращается владельцу, возможно, с повреждениями.', '3 года лишения свободы', NULL, false, 'Смеш', NULL);

Уничтожение — приведение имущества в полную негодность, исключающую его восстановление и использование по назначению. Может быть совершено в любой форме.', '3 года лишения свободы', NULL, false, 'Смеш', NULL);

Хулиганские побуждения — грубое нарушение общественного порядка, пренебрежение правилами поведения в обществе, совершение действий, оскорбляющих окружающих.', '3 года лишения свободы', NULL, false, 'Смеш', NULL);

Государственное имущество — имущество, принадлежащее государству на праве собственности, включая муниципальное имущество.', '3 года лишения свободы', NULL, false, 'Смеш', NULL);

Предпринимательская деятельность — самостоятельная деятельность на свой риск, направленная на систематическое получение прибыли.', '3 года лишения свободы', '20 000–30 000$', false, 'Фин', 'Не распространяется на фермерство, охоту, рыбалку и куплю-продажу личных вещей.');

Угрозы: насилие, уничтожение или повреждение имущества. Сделка может быть не заключена, но принуждение уже образует состав преступления.', '3 года лишения свободы', NULL, false, 'Фин', NULL);

Уклонение — непредставление налоговой декларации, включение заведомо ложных сведений, иные способы умышленного неисполнения обязанности по уплате налогов.', '5 лет + долг ×2', NULL, true, 'Фин', NULL);

Сокрытие — действия, направленные на то, чтобы сделать имущество недоступным для взыскания: перевод на подставных лиц, вывоз, уничтожение, сокрытие.', '3 года лишения свободы', NULL, false, 'Фин', NULL);

Формы: соглашения о ценах, разделе рынка, ограничении доступа на рынок, использование служебного положения для создания преимуществ или ограничений.', '4 года лишения свободы', NULL, true, 'Фин', NULL);

Целевое использование — расходование средств строго по назначению, определённому при их выделении. Премирование — выплата премий при отсутствии установленной отчётности или оснований.', '5 лет лишения свободы', NULL, true, 'Фин', NULL);

Финансирование — предоставление или сбор средств, оказание финансовых услуг, передача имущества, заведомо предназначенных для финансирования экстремистской деятельности в любой форме.', '5 лет лишения свободы', NULL, true, 'Фин', NULL);

Цель терроризма — воздействие на принятие решений органами власти путём устрашения населения и создания опасности.', '5 лет лишения свободы', NULL, true, 'Фед', 'Сроки давности не применяются.');

Оправдание терроризма — публичное признание идеологии и практики терроризма правильными, заслуживающими поддержки. Пропаганда — распространение материалов, направленных на формирование идеологии терроризма.', '5 лет лишения свободы', NULL, true, 'Смеш', NULL);

Ложное сообщение — информация, не соответствующая действительности, о готовящемся взрыве, поджоге или иных действиях, создающих опасность. Состав формальный — не требуется реального причинения вреда.', '4 года лишения свободы', NULL, true, 'Смеш', NULL);

Ответственность наступает независимо от того, удалось ли возбудить ненависть. Достаточно самого факта совершения действий, направленных на это.', '2 года лишения свободы', '20 000$', false, 'Смеш', NULL);

Отягчающие обстоятельства: с применением насилия или угрозой его применения, лицом с использованием своего служебного положения, организованной группой.', '4 года лишения свободы', '50 000$', true, 'Смеш', NULL);

Формы участия: организация деятельности ликвидированной организации, склонение к участию, вербовка, вовлечение, участие в деятельности.', '5 лет лишения свободы', NULL, true, 'Фед', 'Лицо, добровольно прекратившее участие в экстремистской организации и активно способствовавшее раскрытию преступления, освобождается от уголовной ответственности.');

Неоднократность — совершение деяния более одного раза. Достаточно двух и более нарушений.', '3 года лишения свободы', NULL, false, 'Смеш', NULL);

Массовые беспорядки — действия значительного числа лиц, сопровождающиеся насилием, погромами, поджогами, уничтожением имущества, применением оружия, вооружённым сопротивлением власти.', '5 лет лишения свободы', NULL, true, 'Смеш', NULL);

Охраняемый объект — объект, доступ на который ограничен в установленном порядке (государственные учреждения, режимные объекты).', '3 года лишения свободы', '20 000–50 000$', false, 'Смеш', NULL);

Особо охраняемый объект — объект, имеющий особое значение для безопасности государства (Форт-Занкудо, Офис FIB).', '4-5 лет лишения свободы', '60 000–80 000$', true, 'Смеш', NULL);

Квалифицирующий признак: деяние совершено лицом, обладающим властными полномочиями, которое в силу своего служебного положения должно обеспечивать охрану правопорядка, а не нарушать его. Ответственность наступает независимо от того, использовало ли лицо свои служебные полномочия при совершении деяния.', '5 лет лишения свободы', '60 000–80 000$', true, 'Смеш', NULL);

Виды операций: приобретение, передача, сбыт, перевозка. Незаконными считаются операции, совершённые без соответствующего разрешения.', '4 года лишения свободы', '10 000–30 000$', true, 'Смеш', 'Лицензию изымаешь.');

Хранение — нахождение оружия во владении лица. Ношение — перемещение оружия при себе. Использование — применение оружия по назначению.', '4 года лишения свободы', '10 000–30 000$', true, 'Смеш', 'Лицензию изымаешь. Исключение: уполномоченные лица в соответствии с Законом ''О детективной деятельности''.');

Спецсредства гособразца: бронежилеты, тазеры, дубинки, медицинское оборудование, оружие, имеющие серийные номера государственного образца.', '5 лет лишения свободы', NULL, true, 'Смеш', 'Исключение: уполномоченные лица в соответствии с Законом ''О детективной деятельности''.');

Взрывчатые вещества — химические соединения и смеси, способные к взрыву. Взрывные устройства — изделия, конструктивно предназначенные для взрыва.', '5 лет лишения свободы', NULL, true, 'Смеш', NULL);

Хищение — незаконное безвозмездное изъятие оружия из владения собственника. Ответственность наступает независимо от стоимости похищенного.', '4 года лишения свободы', NULL, true, 'Смеш', NULL);

Вооружённое формирование — группа лиц, имеющая оружие, организованная для достижения определённых целей, создание которой не предусмотрено законом.', '5 лет лишения свободы', NULL, true, 'Фед', NULL);

Преступное сообщество — структурированная организованная группа, действующая под единым руководством, объединённая для совершения тяжких или особо тяжких преступлений.', '5 лет лишения свободы', NULL, true, 'Фед', 'Лицо, добровольно прекратившее участие в преступном сообществе и активно способствовавшее раскрытию преступления, освобождается от уголовной ответственности, если в его действиях нет иного состава преступления.');

Способы получения: похищение, обман (мошенничество), шантаж, принуждение, угроза насилием, иные незаконные способы.', '5 лет лишения свободы', NULL, true, 'Фед', NULL);

Кустарное производство — выращивание, удобрение, полив кустарников, содержащих наркотические вещества. Сорняк кустарником не является.', '3 года лишения свободы', '20 000–40 000$', false, 'Смеш', 'Сам сорняк не является кустарником. Полив сорняков не образует состава.');

Количество: от 3 до 25 граммов включительно. Хранение — нахождение наркотиков при себе, в жилище, в тайнике. Перевозка — перемещение на любом виде транспорта.', '4 года лишения свободы', '40 000–60 000$', true, 'Смеш', 'Наличие лицензии KNN разрешает хранение до 5 граммов легально. Исключение: уполномоченные лица в соответствии с Законом ''О детективной деятельности''.');

Крупный размер — свыше 25 граммов. Цель сбыта — намерение передать наркотики другому лицу возмездно или безвозмездно.', '5 лет лишения свободы', NULL, true, 'Смеш', NULL);

Организация — создание места для занятия проституцией, вербовка лиц, принуждение к занятию проституцией. Вовлечение — склонение к занятию проституцией любым способом.', '3 года лишения свободы', '25 000–50 000$', false, 'Рег', NULL);

Особая ответственность госслужащих обусловлена тем, что они призваны бороться с преступностью, а не совершать её. Исключение — сотрудники DEA, K-9, CID, DB при исполнении.', '5 лет лишения свободы', NULL, true, 'Смеш', 'Исключение: DEA, K-9, CID, DB при исполнении служебных обязанностей, а также иные уполномоченные лица в соответствии с Законом ''О детективной деятельности''.');

Поддельные документы — накладные, счета-фактуры и иные товаросопроводительные документы, содержащие заведомо ложные сведения.', '3 года лишения свободы', '25 000–50 000$', false, 'Смеш', NULL);

Отягчающие обстоятельства: группой лиц по предварительному сговору, с использованием служебного положения.', '4 года лишения свободы', '40 000–70 000$', true, 'Смеш', NULL);

Дискредитация — распространение заведомо ложных сведений, порочащих деятельность госорганов, подрыв доверия к ним. Обязательно наступление последствий — существенное нарушение прав граждан, общества или государства.', '5 лет лишения свободы', NULL, true, 'Смеш', NULL);

Насильственный захват власти — противоправные действия, направленные на отстранение законной власти и установление своей.', '5 лет лишения свободы', NULL, true, 'Смеш', NULL);

Сепаратизм — публичные призывы к отделению, организация незаконных референдумов, создание органов власти на отделяемой территории, иные действия, направленные на нарушение территориальной целостности.', '5 лет лишения свободы', NULL, true, 'Фед', NULL);

Государственная тайна — защищаемые государством сведения в области военной, внешнеполитической, разведывательной, контрразведывательной деятельности, распространение которых может нанести ущерб безопасности.', '4 года лишения свободы', NULL, true, 'Фед', NULL);

Способы получения: похищение документов, обман, шантаж, принуждение, угроза насилием, иные незаконные способы.', '4 года лишения свободы', NULL, true, 'Фед', NULL);

Утрата — выход документов из владения лица, которому они были доверены, при отсутствии умысла на их передачу. Обязательны тяжкие последствия.', '4 года лишения свободы', NULL, true, 'Фед', NULL);

Явный выход за пределы полномочий — совершение действий, которые никто и ни при каких обстоятельствах не вправе совершать, либо совершение их единолично, когда требуется коллегиальное решение, либо совершение в отношении не того круга лиц.', '4 года лишения свободы', '40 000–100 000$', true, 'Смеш', NULL);

Отягчающие обстоятельства: с применением насилия или угрозой его применения, с применением оружия или специальных средств, с причинением тяжких последствий, группой лиц, из корыстной заинтересованности.', '5 лет лишения свободы', NULL, true, 'Смеш', NULL);

Отличие от превышения: при злоупотреблении действия не выходят за пределы формальных полномочий, но совершаются вопреки интересам службы из корыстной или иной личной заинтересованности.', '5 лет лишения свободы', '50 000–100 000$', true, 'Смеш', 'При назначении штрафа судимости не возникает.');

Приказ должен быть отдан в установленном порядке и не противоречить закону. Неисполнение приказа, заведомо незаконного, не влечёт ответственности по данной статье.', '4 года лишения свободы', '30 000–40 000$', true, 'Смеш', NULL);

Внешние признаки: ношение форменной одежды, служебных знаков, использование служебных документов, представление себя уполномоченным лицом. Обязательно наступление последствий.', '3 года лишения свободы', '30 000–60 000$', false, 'Смеш', NULL);

Взятка — любое имущество, услуги, выгода, предоставляемые должностному лицу за совершение действий (бездействия) в пользу взяткодателя. Состав считается оконченным с момента принятия хотя бы части взятки.', '5 лет лишения свободы', NULL, true, 'Смеш', 'Сроки давности не применяются.');

Дача взятки считается оконченной с момента принятия взятки должностным лицом. Лицо, добровольно сообщившее о даче взятки, может быть освобождено от ответственности.', '5 лет лишения свободы', NULL, true, 'Смеш', NULL);

Посредничество — передача взятки по поручению, организация встречи, помощь в достижении соглашения, иное способствование.', '5 лет лишения свободы', NULL, true, 'Смеш', NULL);

Халатность — преступление против интересов службы, совершённое по неосторожности. Должностное лицо либо не исполняет обязанности, либо исполняет их ненадлежащим образом.', '4 года лишения свободы', '40 000–70 000$', true, 'Смеш', NULL);

Квалифицирующий признак — наступление тяжкого вреда здоровью или смерти человека по неосторожности в результате халатности должностного лица.', '5 лет лишения свободы', NULL, true, 'Смеш', NULL);

Квалифицирующие признаки: систематичность, публичность немотивированной агрессии, использование служебного положения для психологического давления, провокация массовых беспорядков.', '3 года лишения свободы', '20 000–60 000$', false, 'Смеш', 'Единичные резкие высказывания без тяжких последствий не образуют состава.');

Формы вмешательства: давление на судью, угрозы, подкуп, распространение ложных сведений, иные действия, направленные на изменение судебного решения.', '4 года лишения свободы', NULL, true, 'Фед', NULL);

Формы вмешательства: давление, угрозы, подкуп, уничтожение документов, иные действия, направленные на воспрепятствование расследованию.', '4 года лишения свободы', NULL, true, 'Фед', NULL);

Использование служебного положения — давление на судью, прокурора или следователя с использованием властных полномочий.', '4 года лишения свободы', NULL, true, 'Фед', NULL);

Неуважение к суду — оскорбление судьи, нарушение порядка в зале суда, невыполнение распоряжений председательствующего.', '4-5 лет лишения свободы', '15 000–70 000$', true, 'Фед', NULL);

Формы вмешательства: физическое или психическое воздействие, изъятие документов, ограничение доступа к подзащитному, нарушение адвокатской тайны.', '4 года лишения свободы', '40 000–80 000$', true, 'Фед', NULL);

Использование служебного положения — давление на защитника, угроза увольнением, создание административных барьеров, незаконный обыск.', '4-5 лет лишения свободы', NULL, true, 'Фед', NULL);

Посягательство на жизнь — умышленные действия, непосредственно направленные на лишение жизни указанных лиц. Угроза — высказывание намерения совершить убийство.', '5 лет лишения свободы', NULL, true, 'Смеш', 'Сроки давности не применяются.');

Заведомая невиновность — лицо не совершало инкриминируемого деяния, и об этом достоверно известно привлекающему к ответственности.', '5 лет лишения свободы', NULL, true, 'Смеш', 'Сроки давности не применяются.');

Незаконное задержание — отсутствие законных оснований для задержания, нарушение порядка задержания, превышение сроков.', '5 лет лишения свободы', NULL, true, 'Смеш', 'Сроки давности не применяются.');

Фальсификация — подделка документов, фабрикация вещественных доказательств, внесение ложных сведений в протоколы.', '5 лет лишения свободы', NULL, true, 'Смеш', NULL);

Фальсификация — подделка документов, фабрикация улик, внесение ложных сведений в протоколы следственных действий.', '5 лет лишения свободы', NULL, true, 'Фед', NULL);

Неправомерный приговор — решение, заведомо противоречащее закону, основанное на ложных доказательствах или вынесенное в отсутствие состава преступления.', '5 лет лишения свободы', NULL, true, 'Фед', NULL);

Заведомая ложность означает, что лицо осознаёт, что сообщаемые им сведения не соответствуют действительности, переводит неверно либо даёт заведомо неверное заключение.', '4 года лишения свободы', NULL, true, 'Смеш', 'За дачу заведомо ложных показаний в ходе предварительного следствия ответственность наступает по ст.16.13.1. Отказ от дачи показаний ответственности не влечёт.');

Подкуп — передача денег, ценностей, оказание услуг, предоставление имущественных выгод.', '4 года лишения свободы', NULL, true, 'Смеш', NULL);

Злостность — умышленное, систематическое уклонение от исполнения, создание препятствий, игнорирование требований.', '4 года лишения свободы', '30 000–70 000$', true, 'Смеш', NULL);

Злостность — умышленное, систематическое уклонение от исполнения, игнорирование требований судебного акта.', '5 лет лишения свободы', '40 000–80 000$', true, 'Смеш', NULL);

Улики — предметы, документы, следы, имеющие значение для расследования. Сокрытие — действия, направленные на то, чтобы сделать улики недоступными. Уничтожение — приведение улик в состояние, исключающее их использование.', '4 года лишения свободы', NULL, true, 'Смеш', NULL);

Формы уклонения: смена места жительства, использование подложных документов, изменение внешности, иные действия, препятствующие задержанию или рассмотрению дела.', '4 года лишения свободы', NULL, true, 'Смеш', NULL);

Показания — сведения, сообщённые прокурору в ходе осуществления им процессуальных полномочий. Заведомая ложность означает, что лицо знает о несоответствии сведений действительности.', '4 года лишения свободы', '30 000–50 000$', true, 'Смеш', NULL);

Отличие от ст.16.8: ложные показания даются не в суде, а на стадии предварительного расследования.', '4 года лишения свободы', '50 000–80 000$', true, 'Смеш', NULL);

Отказ от дачи показаний — заявление об отказе дать показания. Уклонение от освидетельствования — неявка, создание препятствий.', '3 года лишения свободы', NULL, false, 'Смеш', NULL);

Уклонение — самовольное оставление места отбывания наказания, невозвращение в установленный срок, смена места жительства без уведомления, иные действия.', '10-19 суток КПЗ или 2-5 лет тюрьмы', NULL, true, 'Смеш', 'Явка с повинной даёт 1/2 наказания.');

Посягательство на жизнь — умышленные действия, непосредственно направленные на лишение жизни. Считается оконченным независимо от наступления смерти.', '5 лет лишения свободы', NULL, true, 'Смеш', 'Сроки давности не применяются.');

Оскорбление — унижение чести и достоинства, выраженное в неприличной или иной, противоречащей общепринятым нормам морали и нравственности, форме.', '3 года лишения свободы', '20 000–50 000$', false, 'Смеш', NULL);

Самоуправство — совершение действий, которые лицо не вправе совершать в том порядке, в котором их совершает, либо совершение действий, которые вообще не вправе совершать.', '3 года лишения свободы', NULL, false, 'Смеш', NULL);

Неповиновение — отказ выполнить законное требование сотрудника при исполнении им служебных обязанностей. Воспрепятствование — создание препятствий для выполнения служебных обязанностей.', '3 года лишения свободы', '20 000–60 000$', false, 'Смеш', NULL);

Отказ — передача штрафного тикета обратно, его порча, устный или письменный отказ, игнорирование штрафного тикета.', '3 года лишения свободы', '20 000–60 000$', false, 'Смеш', NULL);

Подделка — изготовление подложного документа. Использование — предъявление заведомо подложного документа как подлинного.', '4 года лишения свободы', NULL, true, 'Смеш', 'Примечание: Лицензия Частного Адвоката не является незарегистрированной в случае отсутствия таковой в реестре Частных Адвокатов.');

Приказ должен быть отдан в установленном порядке и не противоречить закону. Приказ, заведомо незаконный, исполнению не подлежит.', '3 года лишения свободы', '10 000–25 000$', false, 'Воен', NULL);

Самовольное оставление — уход с места службы без разрешения. Неявка — отсутствие на службе после увольнения без уважительной причины.', '3 года лишения свободы', '10 000–30 000$', false, 'Воен', NULL);

Отличие от самовольного оставления: наличие цели навсегда уклониться от военной службы. Дезертирство считается более тяжким воинским преступлением.', '4 года лишения свободы', '15 000–40 000$', true, 'Воен', NULL);

Нарушение может выражаться в оставлении поста, сне на посту, несвоевременном обнаружении приближающегося противника и т.п.', '3 года лишения свободы', '20 000$', false, 'Воен', NULL);

Уничтожение — приведение в полную негодность. Повреждение — частичное приведение в негодность, требующее ремонта.', '3 года лишения свободы', NULL, false, 'Воен', NULL);

Нарушение правил вождения — превышение скорости, игнорирование сигналов светофора, нарушение правил обгона и т.п. при управлении военной техникой.', '4 года лишения свободы', NULL, true, 'Воен', NULL);

Опасный тип животных определяется в соответствии с Законом ''Об охоте и сохранении охотничьих ресурсов''.', '3 года лишения свободы', '20 000–60 000$', true, 'Смеш', NULL);

Заповедный тип животных определяется в соответствии с Законом ''Об охоте и сохранении охотничьих ресурсов''. Охота на таких животных строго запрещена или возможна только по специальным разрешениям.', '3 года лишения свободы', '40 000–60 000$', true, 'Смеш', NULL);

Квалифицирующий признак: лицо уже привлекалось к административной ответственности за аналогичное нарушение в течение последних 14 дней.', '3 года лишения свободы', '20 000–40 000$', true, 'Смеш', NULL);

Жестокое обращение — нанесение побоев, истязание, лишение пищи, воды, крова, иные действия, причиняющие боль и страдания. Обязательно последствия — гибель или увечье животного.', '2 года лишения свободы', '10 000–40 000$', false, 'Рег', NULL);

Отягчающие обстоятельства: группой лиц, в присутствии малолетнего, с садистскими методами, с публичной демонстрацией, в отношении нескольких животных.', '3 года лишения свободы', NULL, false, 'Рег', NULL);

Насилие — физическое принуждение животного к совершению действий. Беспомощное состояние — невозможность животного оказать сопротивление.', '2 года лишения свободы', NULL, false, 'Рег', NULL);

Отягчающие обстоятельства: группой лиц, соединённое с угрозой убийством или причинением тяжкого вреда здоровью, совершённое с особой жестокостью по отношению к животному, повлёкшее по неосторожности смерть животного.', '3 года лишения свободы', NULL, false, 'Рег', NULL);


CREATE TABLE IF NOT EXISTS favourites (
    id          SERIAL PRIMARY KEY,
    user_id     VARCHAR(64) NOT NULL,
    item_type   VARCHAR(10) NOT NULL CHECK (item_type IN ('article','info')),
    item_id     INT NOT NULL,
    sort_order  INT DEFAULT 0,
    created_at  TIMESTAMPTZ DEFAULT NOW()
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_fav_unique ON favourites(user_id, item_type, item_id);
CREATE INDEX IF NOT EXISTS idx_fav_user ON favourites(user_id, sort_order);
