INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава VI. Преступления против жизни и здоровья', 'ст.6.1 ч.1', '⭐⭐⭐', 'Побои / лёгкий вред здоровью', 'Умышленное нанесение побоев или совершение иных насильственных действий, причинивших физическую боль либо телесные повреждения легкой или средней тяжести', 'Диспозиция: Объект — здоровье человека. Объективная сторона — нанесение побоев или иных насильственных действий, причинивших физическую боль либо легкий/средний вред здоровью. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава VI. Преступления против жизни и здоровья', 'ст.6.1 ч.2', '⭐⭐⭐⭐', 'Тяжкие телесные повреждения', 'Умышленное нанесение особо тяжких телесных повреждений', 'Диспозиция: Объект — здоровье человека. Объективная сторона — умышленное причинение тяжкого вреда здоровью. Субъект — вменяемое лицо от 14 лет. Субъективная сторона — прямой или косвенный умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава VI. Преступления против жизни и здоровья', 'ст.6.1 ч.3', '⭐⭐⭐', 'Тяжкие повреждения по неосторожности/аффекту', 'Нанесение особо тяжких телесных повреждений по неосторожности или в состоянии аффекта', 'Диспозиция: Объект — здоровье человека. Объективная сторона — причинение тяжкого вреда здоровью. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — неосторожность (легкомыслие или небрежность) либо состояние аффекта.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава VI. Преступления против жизни и здоровья', 'ст.6.2 ч.1', '⭐⭐⭐⭐', 'Убийство', 'Умышленное причинение смерти другому человеку', 'Диспозиция: Объект — жизнь человека. Объективная сторона — противоправное лишение жизни другого человека. Субъект — вменяемое лицо от 14 лет. Субъективная сторона — прямой или косвенный умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава VI. Преступления против жизни и здоровья', 'ст.6.2 ч.2', '⭐⭐⭐', 'Убийство по неосторожности/аффекту', 'Причинение смерти по неосторожности или в состоянии аффекта', 'Диспозиция: Объект — жизнь человека. Объективная сторона — причинение смерти. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — неосторожность (легкомыслие или небрежность) либо состояние аффекта.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава VI. Преступления против жизни и здоровья', 'ст.6.3', '⭐⭐⭐⭐⭐', 'Тяжкое убийство', 'Убийство двух или более лиц, с особой жестокостью, общеопасным способом, группой лиц, из корысти, по найму, в связи со служебной деятельностью', 'Диспозиция: Объект — жизнь человека. Объективная сторона — убийство при отягчающих обстоятельствах. Субъект — вменяемое лицо от 14 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава VI. Преступления против жизни и здоровья', 'ст.6.6', '⭐⭐⭐', 'Угроза убийством', 'Угроза убийством или причинением тяжкого вреда здоровью, если имелись основания опасаться осуществления этой угрозы', 'Диспозиция: Объект — психическая неприкосновенность, здоровье, жизнь. Объективная сторона — высказывание угрозы убийством или причинением тяжкого вреда здоровью. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава VI. Преступления против жизни и здоровья', 'ст.6.7', '⭐⭐⭐', 'Воспрепятствование работе медработника', 'Воспрепятствование в какой бы то ни было форме законной деятельности медицинского работника по оказанию медицинской помощи', 'Диспозиция: Объект — установленный порядок оказания медицинской помощи. Объективная сторона — воспрепятствование законной деятельности медработника. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава VII. Против свободы, чести и достоинства', 'ст.7.1', '⭐⭐⭐⭐⭐', 'Похищение человека', 'Незаконный захват, перемещение и удержание человека, в том числе в целях понуждения государства, организации или гражданина совершить какое-либо действие', 'Диспозиция: Объект — личная свобода человека. Объективная сторона — незаконный захват, перемещение и последующее удержание потерпевшего. Субъект — вменяемое лицо от 14 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава VII. Против свободы, чести и достоинства', 'ст.7.1.1', '⭐⭐⭐⭐', 'Незаконное лишение свободы', 'Незаконное лишение свободы, не связанное с его похищением', 'Диспозиция: Объект — личная свобода человека. Объективная сторона — незаконное лишение человека свободы, не связанное с его похищением (например, запирание в помещении). Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава VII. Против свободы, чести и достоинства', 'ст.7.2', '⭐⭐⭐⭐', 'Использование рабского труда', 'Использование рабского труда человека, в отношении которого осуществляются полномочия, присущие праву собственности, если лицо по не зависящим от него причинам не может отказаться от выполнения работ', 'Диспозиция: Объект — свобода и достоинство личности. Объективная сторона — использование рабского труда. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава VII. Против свободы, чести и достоинства', 'ст.7.3', '⭐⭐⭐⭐', 'Сделки с куплей-продажей человека', 'Любые сделки, связанные с куплей-продажей человека, совершённые в целях его эксплуатации, вербовки, получения выгоды', 'Диспозиция: Объект — свобода и достоинство личности. Объективная сторона — совершение сделок купли-продажи человека. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава VII. Против свободы, чести и достоинства', 'ст.7.4 ч.1', '⭐⭐', 'Клевета', 'Распространение заведомо ложных сведений, порочащих честь и достоинство другого лица или подрывающих его репутацию', 'Диспозиция: Объект — честь и достоинство личности. Объективная сторона — распространение заведомо ложных сведений, порочащих честь и достоинство потерпевшего. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава VII. Против свободы, чести и достоинства', 'ст.7.4 ч.2', '⭐⭐', 'Клевета в публичном выступлении', 'Клевета, содержащаяся в публичном выступлении, СМИ, интернете либо в отношении нескольких лиц', 'Диспозиция: Объект — честь и достоинство личности. Объективная сторона — распространение клеветы публично, в СМИ или интернете, либо в отношении нескольких лиц. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава VII. Против свободы, чести и достоинства', 'ст.7.4 ч.3', '⭐⭐⭐', 'Клевета с использованием должностного положения', 'Клевета, совершённая с использованием своего служебного положения', 'Диспозиция: Объект — честь и достоинство личности. Объективная сторона — распространение клеветы с использованием служебного положения. Субъект специальный — лицо, использующее своё служебное положение. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава VII. Против свободы, чести и достоинства', 'ст.7.4 ч.4', '⭐⭐', 'Клевета о заболевании', 'Клевета о том, что лицо страдает заболеванием, представляющим опасность для окружающих', 'Диспозиция: Объект — честь и достоинство личности. Объективная сторона — распространение клеветы о наличии у потерпевшего опасного заболевания. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава VII. Против свободы, чести и достоинства', 'ст.7.4 ч.5', '⭐⭐⭐', 'Клевета об особо тяжком преступлении', 'Клевета, соединённая с обвинением лица в совершении преступления против половой неприкосновенности либо тяжкого или особо тяжкого преступления', 'Диспозиция: Объект — честь и достоинство личности. Объективная сторона — клевета с обвинением в совершении тяжкого или особо тяжкого преступления либо преступления против половой неприкосновенности. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава VIII. Половая неприкосновенность', 'ст.8.1 ч.1', '⭐⭐⭐⭐', 'Изнасилование', 'Половое сношение с применением насилия или с угрозой его применения к потерпевшей или к другим лицам либо с использованием беспомощного состояния потерпевшей', 'Диспозиция: Объект — половая неприкосновенность и половая свобода личности. Объективная сторона — половое сношение с применением насилия, угрозой его применения либо с использованием беспомощного состояния. Субъект — вменяемое лицо от 14 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава VIII. Половая неприкосновенность', 'ст.8.1 ч.2', '⭐⭐⭐⭐', 'Изнасилование группой', 'Изнасилование, совершённое группой лиц, с угрозой убийством, с особой жестокостью, повлёкшее смерть потерпевшего', 'Диспозиция: Объект — половая неприкосновенность и половая свобода личности. Объективная сторона — изнасилование при отягчающих обстоятельствах. Субъект — вменяемое лицо от 14 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава VIII. Половая неприкосновенность', 'ст.8.2', '⭐⭐⭐', 'Понуждение к половому акту', 'Понуждение лица к половому сношению путём шантажа, угрозы уничтожением или повреждением имущества либо с использованием материальной или иной зависимости', 'Диспозиция: Объект — половая свобода личности. Объективная сторона — понуждение к половому сношению, мужеложству, лесбиянству или иным действиям сексуального характера. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава VIII. Половая неприкосновенность', 'ст.8.3', '⭐⭐⭐', 'Сексуальное домогательство', 'Действия с использованием явного или скрытого сексуального подтекста, включая нежелательные и неуместные обещания вознаграждения в обмен на сексуальные услуги', 'Диспозиция: Объект — половая свобода и достоинство личности. Объективная сторона — сексуальное домогательство в любой форме. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава IX. Против конституционных прав', 'ст.9.1', '⭐⭐⭐⭐⭐', 'Воспрепятствование выборам', 'Воспрепятствование свободному осуществлению гражданином своих избирательных прав, в том числе соединённое с подкупом, обманом, принуждением, применением насилия либо с угрозой его применения', 'Диспозиция: Объект — избирательные права граждан. Объективная сторона — воспрепятствование осуществлению избирательных прав. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава IX. Против конституционных прав', 'ст.9.2 ч.1', '⭐⭐⭐', 'Воспрепятствование работе Сената', 'Воспрепятствование прибытию сенатора в место проведения заседания Сената, создание условий, которые делают невозможным или затруднительным его присутствие на заседании', 'Диспозиция: Объект — установленный порядок деятельности Сената. Объективная сторона — действия, препятствующие прибытию сенатора на заседание или его участию в заседании. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава IX. Против конституционных прав', 'ст.9.2 ч.2', '⭐⭐⭐', 'Срыв заседания Сената', 'Попытка сорвать идущее заседание Сената путём незаконного проникновения в помещение, создания барьеров, дестабилизации работы электронных систем и средств коммуникации', 'Диспозиция: Объект — установленный порядок деятельности Сената. Объективная сторона — действия, направленные на срыв заседания Сената. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава X. Против собственности', 'ст.10.1', '⭐⭐⭐', 'Кража', 'Тайное хищение чужого имущества стоимостью свыше 15 000$', 'Диспозиция: Объект — собственность. Объективная сторона — тайное изъятие чужого имущества. Субъект — вменяемое лицо от 14 лет. Субъективная сторона — прямой умысел, корыстная цель.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава X. Против собственности', 'ст.10.1.1', '⭐⭐⭐⭐', 'Кража со взломом', 'Тайное хищение чужого имущества, совершённое с предварительным взломом хранилища, помещения, сейфа или иного запирающего устройства', 'Диспозиция: Объект — собственность. Объективная сторона — кража, соединённая с незаконным проникновением в хранилище, помещение или сейф путём взлома. Субъект — вменяемое лицо от 14 лет. Субъективная сторона — прямой умысел, корыстная цель.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава X. Против собственности', 'ст.10.2', '⭐⭐⭐', 'Мошенничество', 'Хищение чужого имущества или приобретение права на чужое имущество путём обмана или злоупотребления доверием', 'Диспозиция: Объект — собственность. Объективная сторона — завладение имуществом или правом на имущество путём обмана или злоупотребления доверием. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел, корыстная цель.
