INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XII. Общественная безопасность', 'ст.12.1', '⭐⭐⭐⭐⭐', 'Терроризм', 'Совершение взрыва, поджога или иных действий, устрашающих население и создающих опасность гибели человека', 'Диспозиция: Объект — общественная безопасность. Объективная сторона — совершение взрыва, поджога или иных общеопасных действий. Субъект — вменяемое лицо от 14 лет. Субъективная сторона — прямой умысел, специальная цель — дестабилизация деятельности органов власти.
