INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XII. Общественная безопасность', 'ст.12.8.1', '⭐⭐⭐⭐⭐', 'Госоружие у гражданского', 'Использование, ношение, хранение гражданскими лицами спецсредств государственного образца', 'Диспозиция: Объект — общественная безопасность. Объективная сторона — использование, ношение, хранение спецсредств гособразца. Субъект — гражданское лицо. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XII. Общественная безопасность', 'ст.12.9', '⭐⭐⭐⭐⭐', 'Взрывчатка', 'Незаконные приобретение, передача, сбыт, хранение, перевозка, изготовление или ношение взрывчатых веществ или взрывных устройств', 'Диспозиция: Объект — общественная безопасность. Объективная сторона — незаконные операции с взрывчатыми веществами. Субъект — вменяемое лицо от 14 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XII. Общественная безопасность', 'ст.12.10', '⭐⭐⭐⭐', 'Хищение оружия', 'Хищение огнестрельного оружия, комплектующих деталей к нему, спецсредств, боеприпасов, взрывчатых веществ или взрывных устройств', 'Диспозиция: Объект — общественная безопасность. Объективная сторона — хищение оружия. Субъект — вменяемое лицо от 14 лет. Субъективная сторона — прямой умысел, корыстная цель.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XII. Общественная безопасность', 'ст.12.11', '⭐⭐⭐⭐⭐', 'Создание вооружённого формирования', 'Создание вооружённого формирования, не предусмотренного законом, руководство таким формированием или его финансирование', 'Диспозиция: Объект — безопасность государства. Объективная сторона — создание, руководство или финансирование незаконного вооружённого формирования. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XII. Общественная безопасность', 'ст.12.12', '⭐⭐⭐⭐⭐', 'Организация преступного сообщества', 'Создание преступного сообщества (преступной организации) или участие в нём', 'Диспозиция: Объект — общественная безопасность. Объективная сторона — создание, руководство или участие в преступном сообществе. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XII. Общественная безопасность', 'ст.12.13', '⭐⭐⭐⭐⭐', 'Получение гостайны незаконным путём', 'Получение сведений, составляющих государственную тайну, путём похищения, обмана, шантажа, принуждения, угрозы применения насилия либо иным незаконным способом', 'Диспозиция: Объект — безопасность государства. Объективная сторона — незаконное получение гостайны. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XIII. Здоровье населения', 'ст.13.1', '⭐⭐⭐', 'Кустарное производство наркотиков', 'Незаконное кустарное производство и сбор наркотических веществ в любых размерах', 'Диспозиция: Объект — здоровье населения. Объективная сторона — кустарное производство и сбор наркотических веществ. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XIII. Здоровье населения', 'ст.13.2', '⭐⭐⭐⭐', 'Хранение наркотиков 3–25 гр', 'Незаконные приобретение, хранение, перевозка наркотических средств в размере 3 грамм и выше', 'Диспозиция: Объект — здоровье населения. Объективная сторона — незаконные приобретение, хранение, перевозка наркотиков. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XIII. Здоровье населения', 'ст.13.2.1', '⭐⭐⭐⭐⭐', 'Хранение/сбыт свыше 25 гр', 'Незаконные приобретение, хранение, перевозка наркотических средств свыше 25 грамм, а равно совершённое с целью сбыта', 'Диспозиция: Объект — здоровье населения. Объективная сторона — незаконные операции с наркотиками в крупном размере или с целью сбыта. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XIII. Здоровье населения', 'ст.13.3', '⭐⭐⭐', 'Организация проституции', 'Организация занятия проституцией или вовлечение в него', 'Диспозиция: Объект — общественная нравственность. Объективная сторона — организация занятия проституцией. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XIII. Здоровье населения', 'ст.13.4', '⭐⭐⭐⭐⭐', 'Наркотики у гос.сотрудника', 'Приобретение, хранение, перевозка, изготовление, сбор, сбыт наркотических веществ сотрудниками госструктур', 'Диспозиция: Объект — здоровье населения, авторитет госслужбы. Объективная сторона — незаконные операции с наркотиками, совершённые госслужащим. Субъект специальный — сотрудник государственной структуры. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XIII. Здоровье населения', 'ст.13.6 ч.1', '⭐⭐⭐', 'Перевозка грузов с поддельными документами', 'Перевозка грузов, подлежащих обязательному декларированию или ограниченных к обороту, с использованием заведомо поддельных товаросопроводительных документов', 'Диспозиция: Объект — установленный порядок перевозки грузов. Объективная сторона — использование поддельных документов. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XIII. Здоровье населения', 'ст.13.6 ч.2', '⭐⭐⭐⭐', 'Перевозка грузов группой лиц', 'Те же действия, совершённые группой лиц по предварительному сговору либо с использованием служебного положения', 'Диспозиция: Объект — установленный порядок перевозки грузов. Объективная сторона — перевозка с поддельными документами при отягчающих обстоятельствах. Субъект — вменяемое лицо от 16 лет, возможно специальный. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XIV. Против конституционного строя', 'ст.14.1', '⭐⭐⭐⭐⭐', 'Дискредитация госорганов', 'Публичные действия, направленные на дискредитацию исполнения государственными органами своих полномочий, повлёкшие существенное нарушение прав граждан', 'Диспозиция: Объект — авторитет государственной власти. Объективная сторона — публичные действия, дискредитирующие госорганы. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XIV. Против конституционного строя', 'ст.14.2', '⭐⭐⭐⭐⭐', 'Насильственный захват власти', 'Действия, направленные на насильственный захват власти или насильственное удержание власти, а равно вооружённый мятеж', 'Диспозиция: Объект — основы конституционного строя. Объективная сторона — насильственный захват власти, удержание власти, вооружённый мятеж. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел, специальная цель — захват власти, изменение конституционного строя.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XIV. Против конституционного строя', 'ст.14.2.1', '⭐⭐⭐⭐⭐', 'Сепаратизм', 'Посягательство на территориальную целостность и неприкосновенность штата Сан-Андреас', 'Диспозиция: Объект — территориальная целостность штата. Объективная сторона — действия, направленные на отделение территории, нарушение целостности. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XIV. Против конституционного строя', 'ст.14.3', '⭐⭐⭐⭐', 'Разглашение гостайны', 'Разглашение сведений, составляющих государственную тайну, лицом, которому она была доверена или стала известна по службе, если эти сведения стали достоянием других лиц', 'Диспозиция: Объект — безопасность государства. Объективная сторона — разглашение (сообщение) сведений, составляющих гостайну, третьим лицам. Субъект специальный — лицо, имеющее допуск к гостайне. Субъективная сторона — неосторожность (может быть и умысел).
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XIV. Против конституционного строя', 'ст.14.3.1', '⭐⭐⭐⭐', 'Незаконное получение гостайны', 'Получение сведений, составляющих государственную тайну, путём похищения, обмана, шантажа, принуждения, угрозы применения насилия либо иным незаконным способом', 'Диспозиция: Объект — безопасность государства. Объективная сторона — незаконное получение сведений, составляющих гостайну. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XIV. Против конституционного строя', 'ст.14.3.2', '⭐⭐⭐⭐', 'Утрата документов с гостайной', 'Нарушение правил обращения с документами, содержащими гостайну, если это повлекло по неосторожности их утрату и наступление тяжких последствий', 'Диспозиция: Объект — безопасность государства. Объективная сторона — утрата документов с гостайной. Субъект специальный — лицо, имеющее допуск к гостайне. Субъективная сторона — неосторожность (к утрате).
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XV. Против власти', 'ст.15.1 ч.1', '⭐⭐⭐⭐', 'Превышение полномочий', 'Совершение должностным лицом действий, явно выходящих за пределы его полномочий, повлёкших существенное нарушение прав и законных интересов граждан или организаций', 'Диспозиция: Объект — нормальная деятельность органов власти. Объективная сторона — совершение действий, явно выходящих за пределы полномочий. Субъект специальный — должностное лицо. Субъективная сторона — прямой или косвенный умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XV. Против власти', 'ст.15.1 ч.2', '⭐⭐⭐⭐⭐', 'Превышение с насилием/оружием', 'Превышение полномочий с применением насилия, оружия, группой лиц, из корысти', 'Диспозиция: Объект — нормальная деятельность органов власти, здоровье граждан. Объективная сторона — превышение полномочий при отягчающих обстоятельствах. Субъект специальный — должностное лицо. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XV. Против власти', 'ст.15.1.1 ч.1', '⭐⭐⭐⭐⭐', 'Злоупотребление полномочиями', 'Использование должностным лицом своих полномочий вопреки интересам службы, повлёкшее существенное нарушение прав граждан или организаций', 'Диспозиция: Объект — нормальная деятельность органов власти. Объективная сторона — использование полномочий вопреки интересам службы. Субъект специальный — должностное лицо. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XV. Против власти', 'ст.15.2 ч.1', '⭐⭐⭐⭐', 'Неисполнение приказа начальника', 'Умышленное неисполнение сотрудником правоохранительного органа приказа начальника, причинившее существенный вред', 'Диспозиция: Объект — установленный порядок подчинённости и исполнения приказов. Объективная сторона — умышленное неисполнение приказа. Субъект специальный — сотрудник правоохранительного органа. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XV. Против власти', 'ст.15.3 ч.2', '⭐⭐⭐', 'Присвоение полномочий гражданским', 'Присвоение гражданским лицом внешних признаков, атрибутов или действий должностного лица, повлёкшее существенное нарушение прав граждан', 'Диспозиция: Объект — нормальная деятельность органов власти. Объективная сторона — присвоение внешних признаков должностного лица. Субъект — гражданское лицо, не являющееся служащим. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XV. Против власти', 'ст.15.4', '⭐⭐⭐⭐⭐', 'Получение взятки', 'Получение должностным лицом лично или через посредника взятки в виде денег, иного имущества либо оказания услуг имущественного характера за совершение действий в пользу взяткодателя', 'Диспозиция: Объект — нормальная деятельность органов власти. Объективная сторона — получение взятки. Субъект специальный — должностное лицо. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XV. Против власти', 'ст.15.5', '⭐⭐⭐⭐⭐', 'Дача взятки', 'Дача взятки должностному лицу лично или через посредника', 'Диспозиция: Объект — нормальная деятельность органов власти. Объективная сторона — дача взятки. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XV. Против власти', 'ст.15.5.1', '⭐⭐⭐⭐⭐', 'Посредничество во взяточничестве', 'Непосредственная передача взятки по поручению взяткодателя или взяткополучателя либо иное способствование в достижении соглашения о получении и даче взятки', 'Диспозиция: Объект — нормальная деятельность органов власти. Объективная сторона — посредничество во взяточничестве. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XV. Против власти', 'ст.15.6 ч.1', '⭐⭐⭐⭐', 'Халатность', 'Неисполнение или ненадлежащее исполнение должностным лицом своих обязанностей вследствие недобросовестного или небрежного отношения к службе, повлёкшее причинение крупного ущерба', 'Диспозиция: Объект — нормальная деятельность органов власти. Объективная сторона — неисполнение или ненадлежащее исполнение обязанностей. Субъект специальный — должностное лицо. Субъективная сторона — неосторожность (небрежность).
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XV. Против власти', 'ст.15.6 ч.2', '⭐⭐⭐⭐⭐', 'Халатность со смертью', 'Халатность, повлёкшая по неосторожности причинение тяжкого вреда здоровью или смерть человека', 'Диспозиция: Объект — нормальная деятельность органов власти, жизнь и здоровье. Объективная сторона — халатность, повлёкшая тяжкие последствия. Субъект специальный — должностное лицо. Субъективная сторона — неосторожность.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XV. Против власти', 'ст.15.7', '⭐⭐⭐', 'Деструктивное поведение', 'Совершение должностным лицом при исполнении служебных обязанностей умышленных действий, выраженных в грубом нарушении общепринятых норм этики, морали и правил служебного поведения', 'Диспозиция: Объект — авторитет государственной власти. Объективная сторона — грубое нарушение норм этики и морали. Субъект специальный — должностное лицо. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVI. Против правосудия', 'ст.16.1 ч.1', '⭐⭐⭐⭐', 'Воспрепятствование правосудию', 'Вмешательство в какой бы то ни было форме в деятельность суда в целях воспрепятствования осуществлению правосудия', 'Диспозиция: Объект — нормальная деятельность суда. Объективная сторона — вмешательство в деятельность суда. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел, специальная цель — воспрепятствовать правосудию.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVI. Против правосудия', 'ст.16.1 ч.2', '⭐⭐⭐⭐', 'Воспрепятствование расследованию', 'Вмешательство в деятельность прокурора или лица, производящего следствие', 'Диспозиция: Объект — нормальная деятельность прокуратуры и следствия. Объективная сторона — вмешательство в деятельность прокурора или следователя. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVI. Против правосудия', 'ст.16.1 ч.3', '⭐⭐⭐⭐', 'Воспрепятствование по должности', 'Воспрепятствование правосудию или расследованию, совершённое с использованием служебного положения', 'Диспозиция: Объект — нормальная деятельность суда, прокуратуры, следствия. Объективная сторона — вмешательство с использованием служебного положения. Субъект специальный — должностное лицо. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVI. Против правосудия', 'ст.16.1 ч.4', '⭐⭐⭐⭐', 'Неуважение к суду', 'Совершение действий, свидетельствующих о явном пренебрежении к установленным правилам судебного разбирательства', 'Диспозиция: Объект — нормальная деятельность суда. Объективная сторона — неуважение к суду, неявка без уважительной причины. Субъект — участник судебного заседания или иное лицо. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVI. Против правосудия', 'ст.16.1.1 ч.1', '⭐⭐⭐⭐', 'Вмешательство в деятельность защитника', 'Совершение в любой форме препятствий осуществлению правомерной деятельности защитника или представителя лица по оказанию правовой помощи', 'Диспозиция: Объект — нормальная деятельность защитника (адвоката) и представителя. Объективная сторона — препятствование их законной деятельности либо нарушение гарантий их деятельности и профессиональной тайны. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVI. Против правосудия', 'ст.16.1.1 ч.2', '⭐⭐⭐⭐', 'Вмешательство в деятельность защитника (по должности)', 'Те же действия, совершённые должностным лицом с использованием своего служебного положения', 'Диспозиция: Объект — нормальная деятельность защитника. Объективная сторона — препятствование деятельности защитника с использованием служебного положения. Субъект специальный — должностное лицо. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVI. Против правосудия', 'ст.16.2', '⭐⭐⭐⭐⭐', 'Посягательство на жизнь судьи', 'Угроза или посягательство на жизнь судьи, прокурора, защитника, эксперта, судебного пристава в связи с рассмотрением дел в суде либо из мести за такую деятельность', 'Диспозиция: Объект — жизнь и здоровье участников правосудия. Объективная сторона — посягательство на жизнь или угроза его совершения. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVI. Против правосудия', 'ст.16.3', '⭐⭐⭐⭐⭐', 'Привлечение заведомо невиновного', 'Привлечение заведомо невиновного к уголовной или административной ответственности', 'Диспозиция: Объект — права и законные интересы личности, интересы правосудия. Объективная сторона — привлечение заведомо невиновного к ответственности. Субъект специальный — лицо, производящее расследование, прокурор. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVI. Против правосудия', 'ст.16.4', '⭐⭐⭐⭐⭐', 'Незаконное задержание', 'Заведомо незаконное задержание, заключение под стражу или содержание под стражей', 'Диспозиция: Объект — права и свободы человека. Объективная сторона — незаконное ограничение свободы. Субъект специальный — должностное лицо, уполномоченное на задержание. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVI. Против правосудия', 'ст.16.5', '⭐⭐⭐⭐⭐', 'Фальсификация доказательств', 'Фальсификация доказательств по гражданскому, административному делу лицом, участвующим в деле, или его представителем', 'Диспозиция: Объект — нормальная деятельность правосудия. Объективная сторона — фальсификация (подделка, фабрикация) доказательств. Субъект — лицо, участвующее в деле, или его представитель. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVI. Против правосудия', 'ст.16.6', '⭐⭐⭐⭐⭐', 'Фальсификация доказательств по УД', 'Фальсификация доказательств по уголовному делу лицом, производящим расследование, прокурором или защитником', 'Диспозиция: Объект — нормальная деятельность правосудия. Объективная сторона — фальсификация доказательств по уголовному делу. Субъект специальный — следователь, прокурор, защитник. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVI. Против правосудия', 'ст.16.7', '⭐⭐⭐⭐⭐', 'Неправомерный приговор', 'Вынесение судьёй заведомо неправомерного приговора, решения или иного судебного акта', 'Диспозиция: Объект — нормальная деятельность правосудия. Объективная сторона — вынесение заведомо неправомерного судебного акта. Субъект специальный — судья. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVI. Против правосудия', 'ст.16.8', '⭐⭐⭐⭐', 'Заведомо ложные показания в суде', 'Заведомо ложные показания свидетеля, потерпевшего либо заключение или показание эксперта, показание специалиста в суде', 'Диспозиция: Объект — нормальная деятельность суда. Объективная сторона — дача заведомо ложных показаний, заключения или их перевод. Субъект — свидетель, потерпевший, эксперт, специалист, переводчик. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVI. Против правосудия', 'ст.16.9', '⭐⭐⭐⭐', 'Подкуп свидетеля', 'Подкуп свидетеля, потерпевшего в целях дачи ими ложных показаний либо эксперта, специалиста в целях дачи ими ложного заключения или ложных показаний', 'Диспозиция: Объект — нормальная деятельность правосудия. Объективная сторона — подкуп указанных лиц. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел, специальная цель — дача ложных показаний или заключения.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVI. Против правосудия', 'ст.16.10 ч.1', '⭐⭐⭐⭐', 'Неисполнение судебного акта', 'Злостное неисполнение вступившего в законную силу приговора суда, решения, ордера, постановления', 'Диспозиция: Объект — нормальная деятельность правосудия. Объективная сторона — неисполнение судебного акта. Субъект — лицо, обязанное исполнить судебный акт. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVI. Против правосудия', 'ст.16.10 ч.2', '⭐⭐⭐⭐⭐', 'Неисполнение судебного акта (по должности)', 'Неисполнение судебного акта представителем власти, государственным служащим', 'Диспозиция: Объект — нормальная деятельность правосудия. Объективная сторона — неисполнение судебного акта должностным лицом. Субъект специальный — представитель власти, госслужащий. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVI. Против правосудия', 'ст.16.11', '⭐⭐⭐⭐', 'Сокрытие улик', 'Сокрытие или уничтожение улик', 'Диспозиция: Объект — нормальная деятельность правосудия. Объективная сторона — сокрытие или уничтожение улик (вещественных доказательств). Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVI. Против правосудия', 'ст.16.12', '⭐⭐⭐⭐', 'Уклонение от расследования', 'Уклонение от расследования, задержания и суда, намеренные действия, направленные на уклонение от реального уголовного срока', 'Диспозиция: Объект — нормальная деятельность правосудия. Объективная сторона — уклонение от расследования, задержания, суда. Субъект — лицо, в отношении которого ведётся расследование. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVI. Против правосудия', 'ст.16.13', '⭐⭐⭐⭐', 'Заведомо ложные показания прокурору', 'Заведомо ложные показания и сведения, данные прокурору в ходе рассмотрения дела или проведения допроса', 'Диспозиция: Объект — нормальная деятельность прокуратуры. Объективная сторона — дача заведомо ложных показаний прокурору. Субъект — свидетель, потерпевший, подозреваемый, обвиняемый. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVI. Против правосудия', 'ст.16.13.1', '⭐⭐⭐⭐', 'Заведомо ложные показания на следствии', 'Заведомо ложные показания свидетеля, потерпевшего, эксперта, специалиста, данные в ходе предварительного следствия', 'Диспозиция: Объект — нормальная деятельность следствия. Объективная сторона — дача заведомо ложных показаний на предварительном следствии. Субъект — свидетель, потерпевший, эксперт, специалист. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVI. Против правосудия', 'ст.16.14', '⭐⭐⭐', 'Отказ свидетеля от показаний', 'Отказ свидетеля или потерпевшего от дачи показаний либо уклонение от прохождения освидетельствования', 'Диспозиция: Объект — нормальная деятельность правосудия. Объективная сторона — отказ от дачи показаний или уклонение от освидетельствования. Субъект — свидетель или потерпевший. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVI. Против правосудия', 'ст.16.15', '⭐-⭐⭐⭐⭐⭐', 'Уклонение от отбывания наказания', 'Уклонение от отбывания ограничения свободы или лишения свободы', 'Диспозиция: Объект — нормальная деятельность уголовно-исполнительной системы. Объективная сторона — уклонение от отбывания наказания. Субъект — лицо, которому назначено наказание. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVII. Против управления', 'ст.17.1', '⭐⭐⭐⭐⭐', 'Посягательство на жизнь сотрудника', 'Посягательство на жизнь сотрудника правоохранительного органа, военнослужащего, при исполнении им своих служебных обязанностей, а равно в связи с их исполнением, либо из мести за такую деятельность.', 'Диспозиция: Объект — жизнь сотрудника правоохранительного органа. Объективная сторона — посягательство на жизнь. Субъект — вменяемое лицо от 14 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVII. Против управления', 'ст.17.2', '⭐⭐⭐⭐', 'Насилие в отношении сотрудника', 'Применение насилия, не опасного для жизни или здоровья, либо угроза применения такого насилия в отношении сотрудника правоохранительных органов, военнослужащего, при исполнении им своих служебных обязанностей, а равно в связи с их исполнением, либо из мести за такую деятельность.', 'Диспозиция: Объект — здоровье сотрудника, порядок управления. Объективная сторона — применение насилия (не опасного для жизни) или угроза его применения. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел, специальная цель — воспрепятствование законной деятельности сотрудника либо месть.', '4 года лишения свободы', NULL, true, 'Смеш', NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVII. Против управления', 'ст.17.3', '⭐⭐⭐', 'Оскорбление представителя власти', 'Оскорбление представителя власти при исполнении им своих должностных обязанностей или в связи с их исполнением.', 'Диспозиция: Объект — честь и достоинство представителя власти, порядок управления. Объективная сторона — оскорбление. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVII. Против управления', 'ст.17.5', '⭐⭐⭐', 'Самоуправство', 'Самовольное, вопреки установленному законом или иным нормативным правовым актом порядку совершение каких-либо действий', 'Диспозиция: Объект — установленный порядок управления. Объективная сторона — самовольное совершение действий в обход установленного порядка. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVII. Против управления', 'ст.17.6', '⭐⭐⭐', 'Неповиновение законному требованию', 'Неповиновение законному распоряжению или требованию правомочного лица либо воспрепятствование исполнению им служебных обязанностей', 'Диспозиция: Объект — порядок управления. Объективная сторона — неповиновение законному требованию. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVII. Против управления', 'ст.17.7', '⭐⭐⭐', 'Отказ от оплаты штрафа', 'Отказ от оплаты штрафа, выписанного правомочным лицом, а равно отказ от возмещения ущерба согласно законодательству', 'Диспозиция: Объект — порядок управления. Объективная сторона — отказ от оплаты штрафа или возмещения ущерба. Субъект — лицо, обязанное оплатить штраф или возместить ущерб. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVII. Против управления', 'ст.17.8', '⭐⭐⭐⭐', 'Подделка удостоверения/лицензии', 'Использование не зарегистрированной лицензии и(или) подделка удостоверения или иного официального документа, предоставляющего права или освобождающего от обязанностей, в целях его использования либо сбыт такого документа и(или) лицензии', 'Диспозиция: Объект — установленный порядок оборота официальных документов. Объективная сторона — подделка документа или использование поддельного документа. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVIII. Военные преступления', 'ст.18.1', '⭐⭐⭐', 'Неисполнение приказа', 'Неисполнение подчинённым приказа начальника, отданного в установленном порядке, причинившее существенный вред интересам службы', 'Диспозиция: Объект — установленный порядок подчинённости в вооружённых силах. Объективная сторона — неисполнение приказа. Субъект — военнослужащий, находящийся в подчинении. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVIII. Военные преступления', 'ст.18.2', '⭐⭐⭐', 'Самовольное оставление части', 'Самовольное оставление части или места службы, а равно неявка в срок без уважительных причин на службу при увольнении из части', 'Диспозиция: Объект — установленный порядок прохождения военной службы. Объективная сторона — самовольное оставление части или неявка на службу. Субъект — военнослужащий. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVIII. Военные преступления', 'ст.18.3', '⭐⭐⭐⭐', 'Дезертирство', 'Самовольное оставление части или места службы в целях уклонения от прохождения военной службы, а равно неявка в тех же целях на службу', 'Диспозиция: Объект — установленный порядок прохождения военной службы. Объективная сторона — оставление части с целью уклонения от службы. Субъект — военнослужащий. Субъективная сторона — прямой умысел, специальная цель — уклонение от военной службы.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVIII. Военные преступления', 'ст.18.4', '⭐⭐⭐', 'Нарушение боевого дежурства', 'Нарушение правил несения боевого дежурства (боевой службы) по своевременному обнаружению и отражению внезапного нападения на охраняемый объект', 'Диспозиция: Объект — боевая готовность войск. Объективная сторона — нарушение правил боевого дежурства. Субъект — военнослужащий, заступивший на боевое дежурство. Субъективная сторона — неосторожность или прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVIII. Военные преступления', 'ст.18.5', '⭐⭐⭐', 'Уничтожение оружия', 'Умышленное уничтожение или повреждение оружия, боеприпасов или предметов военной техники', 'Диспозиция: Объект — боевая готовность войск. Объективная сторона — уничтожение или повреждение военного имущества. Субъект — военнослужащий. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XVIII. Военные преступления', 'ст.18.6', '⭐⭐⭐⭐', 'Нарушение правил вождения', 'Нарушение правил вождения или эксплуатации боевой, специальной или транспортной машины, повлёкшее по неосторожности причинение тяжкого вреда здоровью человека', 'Диспозиция: Объект — безопасность эксплуатации военной техники. Объективная сторона — нарушение правил вождения или эксплуатации. Субъект — военнослужащий, управляющий машиной. Субъективная сторона — неосторожность (к последствиям).
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XIX. Против окружающей среды', 'ст.19.1 ч.1', '⭐⭐⭐', 'Браконьерство (опасные животные)', 'Осуществление охотничьей деятельности без специальной лицензии на профессиональную охоту на животных, приравненных к опасному типу', 'Диспозиция: Объект — окружающая среда, животный мир. Объективная сторона — охота на опасных животных без лицензии. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XIX. Против окружающей среды', 'ст.19.1 ч.2', '⭐⭐⭐', 'Браконьерство (заповедные животные)', 'Осуществление охотничьей деятельности на животных, приравненных к заповедному типу', 'Диспозиция: Объект — окружающая среда, животный мир. Объективная сторона — охота на заповедных животных без соответствующего разрешения. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XIX. Против окружающей среды', 'ст.19.1 ч.3', '⭐⭐⭐', 'Браконьерство (повторно)', 'Осуществление охотничьей деятельности, а также рыболовной деятельности лицом, ранее подвергнутом административной ответственности за браконьерство без лицензии за последние 14 дней', 'Диспозиция: Объект — окружающая среда, животный мир. Объективная сторона — повторное браконьерство без лицензии. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XIX. Против окружающей среды', 'ст.19.2 ч.1', '⭐⭐', 'Жестокое обращение с животными', 'Жестокое обращение с животным в целях причинения ему боли и (или) страданий, повлёкшее его гибель или увечье', 'Диспозиция: Объект — окружающая среда, животный мир. Объективная сторона — жестокое обращение с животным. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XIX. Против окружающей среды', 'ст.19.2 ч.2', '⭐⭐⭐', 'Жестокое обращение с животными (группой)', 'Те же действия группой лиц, в присутствии малолетнего, с садистскими методами, с публичной демонстрацией, в отношении нескольких животных', 'Диспозиция: Объект — окружающая среда, животный мир. Объективная сторона — жестокое обращение при отягчающих обстоятельствах. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XIX. Против окружающей среды', 'ст.19.3 ч.1', '⭐⭐', 'Изнасилование животного', 'Половое сношение с животным с применением насилия или с угрозой его применения с использованием беспомощного состояния животного', 'Диспозиция: Объект — животный мир, общественная нравственность. Объективная сторона — половое сношение с животным. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('uk', 'Глава XIX. Против окружающей среды', 'ст.19.3 ч.3', '⭐⭐⭐', 'Изнасилование животного группой', 'Изнасилование животного группой лиц, с угрозой убийством, с особой жестокостью, повлёкшее смерть животного', 'Диспозиция: Объект — животный мир, общественная нравственность. Объективная сторона — изнасилование животного при отягчающих обстоятельствах. Субъект — вменяемое лицо от 16 лет. Субъективная сторона — прямой умысел.
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.5.1 ч.1', NULL, 'Мелкое хулиганство', 'Оскорбительное приставание к гражданам, действия, несущие угрозу обществу, нецензурная брань, неприличные жесты в местах скопления людей, госучреждениях, парках, скверах, пляжах', NULL, NULL, '3 000–7 000$', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.5.1 ч.2', NULL, 'Мелкое хулиганство (повторно)', 'Повторное совершение мелкого хулиганства', NULL, NULL, '5 000–10 000$', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.5.2', NULL, 'Транспорт внутри учреждений', 'Использование любых видов транспорта (мопед, автомобиль, мотоцикл, велосипед и т.п.) внутри помещений государственных учреждений', NULL, NULL, '20 000$', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.5.3 ч.1', NULL, 'Нахождение в неприемлемом виде', 'Нахождение без любого из элементов верхней одежды в местах большого скопления людей, госучреждениях и прилегающих территориях', NULL, NULL, '5 000–30 000$', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.5.3 ч.2', NULL, 'Распитие/опьянение в общественном месте', 'Потребление алкоголя, наркотических средств в местах большого скопления людей, появление в алкогольном или наркотическом опьянении', NULL, NULL, '5 000–30 000$', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.5.3 ч.3', NULL, 'Несоответствующий внешний вид', 'Нахождение мужчин в беговых шортах/трусах/купальниках, женщин в купальниках/трусах на территории государственных организаций', NULL, NULL, '5 000–30 000$', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.5.6', NULL, 'Нарушение порядка проведения митинга', 'Нарушение организатором/участником публичного мероприятия установленного порядка организации либо проведения собрания или митинга', NULL, NULL, '20 000$', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.5.7', NULL, 'Опасное вождение', 'Совершение безрассудного вождения, угрожающего жизни или здоровью окружающих', NULL, NULL, '20 000–30 000$ + лишение прав', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.5.8', NULL, 'Ложный вызов спецслужб', 'Заведомо ложный вызов полиции, скорой помощи или иных специализированных служб', NULL, NULL, '10 000–25 000$', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.5.9', NULL, 'Неуважение к Сенату', 'Неуважительное поведение в отношении сенаторов, Спикера Сената, неуважение к порядку заседания Сената', NULL, NULL, '20 000–100 000$', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.6.1', NULL, 'Дискриминация', 'Нарушение прав, свобод и законных интересов в зависимости от пола, расы, национальности, языка, происхождения, отношения к религии и др.', NULL, NULL, '10 000–30 000$', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.6.1.1', NULL, 'Дискриминация в сфере труда', 'Ограничение трудовых прав в зависимости от пола, расы, национальности и др. обстоятельств, не связанных с деловыми качествами', NULL, NULL, '150 000$ (работодателю)', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.6.1.2', NULL, 'Нарушение охраны труда', 'Нарушение государственных нормативных требований охраны труда', NULL, NULL, '20 000–50 000$ / юр.лицам 50 000–100 000$', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.6.2', NULL, 'Курение в общественных местах', 'Курение табака, никотинсодержащей продукции на территории общественных мест вне специально отведённых зон, на расстоянии до 10 метров от входов госорганов', NULL, NULL, '5 000–20 000$', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.6.3', NULL, 'Неосторожное повреждение чужого имущества', 'Неосторожное нанесение повреждений чужому имуществу', NULL, NULL, '15 000$ + возмещение ущерба', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.6.4', NULL, 'Нарушение права на обед/отпуск', 'Нарушение работодателем прав сотрудника на обеденный перерыв или отпуск', NULL, NULL, '50 000$ (работодателю)', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.6.5', NULL, 'Несоответствие ПВТР законодательству', 'Несоответствие правил внутреннего трудового распорядка текущему законодательству', NULL, NULL, '30 000$ (работодателю)', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.6.6', NULL, 'Воспрепятствование работе журналистов', 'Воспрепятствование законной профессиональной деятельности журналистов', NULL, NULL, '20 000$', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.6.7', NULL, 'Незаконная торговля', 'Осуществление торговой деятельности в общественных местах', NULL, NULL, '30 000–50 000$', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.7.1', NULL, 'Браконьерство', 'Добыча водных биоресурсов или охота вне специально отведённых мест и/или без соответствующей лицензии', NULL, NULL, '5 000–20 000$ + изъятие', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.7.2', NULL, 'Превышение нормы вылова', 'Превышение нормы вылова рыбы, водных биоресурсов или добычи охотничьих ресурсов', NULL, NULL, '5 000–20 000$ + изъятие', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.8.1', NULL, 'Хранение наркотиков до 3 гр', 'Незаконное хранение наркотических или психотропных веществ в количестве менее 3 граммов', NULL, NULL, '5 000–20 000$', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.9.1', NULL, 'Превышение должностных полномочий', 'Совершение должностным лицом действий, явно выходящих за пределы полномочий, без существенного нарушения прав', NULL, NULL, '10 000–50 000$', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.9.2', NULL, 'Злоупотребление должностными полномочиями', 'Использование должностным лицом полномочий вопреки интересам службы без существенного нарушения прав', NULL, NULL, '10 000–50 000$', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.9.3', NULL, 'Халатность', 'Неисполнение или ненадлежащее исполнение обязанностей вследствие небрежного отношения без крупного ущерба', NULL, NULL, '10 000–40 000$', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.9.4', NULL, 'Необеспечение явки на проверку', 'Необеспечение уполномоченными представителями организации явки на плановую проверку ОГП', NULL, NULL, '50 000–350 000$', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('ak', NULL, 'АК ст.9.5', NULL, 'Нарушение территориальной юрисдикции', 'Нарушение территориальной юрисдикции государственным служащим без оснований, предусмотренных законом', NULL, NULL, '20 000–50 000$', false, NULL, NULL);
