INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('dk', NULL, 'ДК ст.1', NULL, 'Отказ предъявить документы', 'Водитель отказался предъявить лицензию и документы по требованию сотрудника', NULL, NULL, 'до 5 000$', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('dk', NULL, 'ДК ст.2', NULL, 'Отказ остановиться', 'Водитель не остановился по законному требованию сотрудника', NULL, NULL, 'до 5 000$', false, NULL, NULL);
