INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('dk', NULL, 'ДК ст.29', NULL, 'Превышение скорости', 'Превышение установленного скоростного режима', NULL, NULL, 'до 15 000$', false, NULL, NULL);
