INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('dk', NULL, 'ДК ст.38', NULL, 'Остановка на автомагистрали', 'Остановка на автомагистрали без чрезвычайной причины', NULL, NULL, 'до 9 000$ + эвакуация', false, NULL, NULL);
