INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('dk', NULL, 'ДК ст.56', NULL, 'Регистрация ТС', 'Использование ТС без госучёта (актуальной регистрации)', NULL, NULL, 'до 20 000$ + лишение прав', false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('weapon', NULL, 'ст.7', NULL, 'Лицензия на гражданское оружие', 'Выдаётся полицией/шерифом после экзамена ($12.000 + $3.000) при наличии медсправки', NULL, 'Бессрочная. Скрытое ношение.', NULL, false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('weapon', NULL, 'ст.15', NULL, 'Запрет на служебное оружие для гражданских', 'Служебное оружие (с префиксом госоргана) запрещено к продаже/передаче гражданским', NULL, 'ст.12.8 УК', NULL, false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('weapon', NULL, 'ст.18.1', NULL, 'Бронежилеты для гражданских', 'Разрешены лёгкие бронежилеты из Ammunation только при наличии лицензии на оружие', NULL, 'Тяжёлые бронежилеты запрещены', NULL, false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('weapon', NULL, 'ст.21-24', NULL, 'Самооборона', 'Граждане вправе защищать жизнь и жилище оружием. Вред нападающему — без последствий', NULL, 'Не является преступлением', NULL, false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('weapon', NULL, 'ст.25', NULL, 'Скрытое ношение', 'Гражданам разрешено исключительно скрытое ношение оружия (в сумке или кобуре)', NULL, 'Сотрудники госструктур могут носить открыто при исполнении', NULL, false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('weapon', NULL, 'ст.32-35', NULL, 'Лицензия коллекционера', 'Выдаётся на 1 неделю ($75.000 + $30.000 экзамен) главой нацбезопасности или губернатором', NULL, 'Требуется лицензия на гражданское оружие', NULL, false, NULL, NULL);
INSERT INTO articles (section_id, group_name, article, stars, name, description, full_desc, punishment, fine, has_conviction, jurisdiction, important) VALUES ('weapon', NULL, 'ст.35-37', NULL, 'Лицензия парамедика', 'Выдаётся главврачом на 1 месяц ($250.000 + $50.000 экзамен). Позволяет хранить дефибриллятор и эпинефрин', NULL, 'Обязанность уведомить сотрудника о наличии лицензии при задержании', NULL, false, NULL, NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('uk-general', 'Глава I. Задачи и принципы Уголовного кодекса', NULL, NULL, '["📌 СТАТЬЯ 1. Уголовное законодательство штата Сан-Андреас","ч. 1 Уголовное законодательство штата Сан-Андреас состоит из настоящего Кодекса. Новые законы, предусматривающие уголовную ответственность, подлежат включению в настоящий Кодекс.","ч. 2 Настоящий Кодекс основывается на Конституции штата Сан-Андреас и общепризнанных принципах и нормах международного права.","","📌 СТАТЬЯ 1.1. Задачи Уголовного кодекса","Задачами Кодекса являются: охрана прав и свобод человека и гражданина, собственности, общественного порядка и общественной безопасности, окружающей среды, конституционного строя штата, обеспечение мира и безопасности человечества, а также предупреждение преступлений.","","📌 СТАТЬЯ 1.2. Принцип законности","Преступность деяния, а также его наказуемость определяются только настоящим Кодексом. Применение уголовного закона по аналогии не допускается.","","📌 СТАТЬЯ 1.3. Принцип равенства граждан перед законом","Лица, совершившие преступления, равны перед законом независимо от пола, расы, национальности, языка, происхождения, имущественного и должностного положения, места жительства, отношения к религии, убеждений, принадлежности к общественным объединениям, а также других обстоятельств.","","📌 СТАТЬЯ 1.4. Принцип вины","Лицо подлежит уголовной ответственности только за те общественно опасные действия (бездействие) и наступившие последствия, в отношении которых установлена его вина. Объективное вменение (ответственность за невиновное причинение вреда) не допускается.","","📌 СТАТЬЯ 1.5. Принцип справедливости","Наказание должно быть справедливым, то есть соответствовать характеру и степени общественной опасности преступления, обстоятельствам его совершения и личности виновного. Никто не может нести уголовную ответственность дважды за одно и то же преступление.","","📌 СТАТЬЯ 1.6. Принцип гуманизма","Уголовное законодательство обеспечивает безопасность человека. Наказание не может иметь своей целью причинение физических страданий или унижение человеческого достоинства.","","📌 СТАТЬЯ 1.7. Основание уголовной ответственности","Основанием уголовной ответственности является совершение деяния, содержащего все признаки состава преступления, предусмотренного настоящим Кодексом.","","📌 СТАТЬЯ 1.8. Состав преступления","Состав преступления — совокупность объективных и субъективных признаков, которые в сумме определяют общественно опасное деяние как преступление.","","Признаки состава преступления:","• Объект — общественные отношения, которым причиняется ущерб вследствие совершения преступления.","• Субъект — лицо, совершившее преступление, способное нести ответственность (вменяемость, возраст).","• Объективная сторона — внешнее проявление преступления (действие/бездействие, последствия, причинная связь).","• Субъективная сторона — внутреннее психическое отношение лица к совершаемому деянию (вина, мотив, цель).","","Примечание: Наличие всех признаков состава преступления является основанием для признания деяния преступным; отсутствие хотя бы одного из них означает отсутствие состава преступления.","","Виды составов преступления:","• Материальные составы — объективная сторона включает наличие общественно опасных последствий.","• Формальные составы — объективная сторона включает только признаки деяния, последствия не требуются.","• Усечённые составы — момент окончания преступления перенесён на более раннюю стадию (приготовление, покушение).","","📌 СТАТЬЯ 1.9. Судимость","Судимость — правовой статус лица, обусловленный фактом осуждения и назначения наказания, влекущий при повторном совершении преступления правовые последствия.","Лицо считается судимым со дня назначения наказания до момента погашения или снятия судимости.","При назначении наказания в виде уголовного штрафа судимость не возникает.","Судимость запрещает лицу находиться на государственной службе.","","📌 СТАТЬЯ 1.10. Действие уголовного закона во времени","Преступность и наказуемость деяния определяются уголовным законом, действовавшим во время совершения этого деяния. Временем совершения преступления признаётся время совершения общественно опасного действия (бездействия) независимо от времени наступления последствий.","","📌 СТАТЬЯ 1.11. Обратная сила уголовного закона","Закон, устраняющий преступность деяния, смягчающий наказание или иным образом улучшающий положение лица, совершившего преступление, имеет обратную силу. Закон, устанавливающий преступность деяния, усиливающий наказание или иным образом ухудшающий положение лица, обратной силы не имеет."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('uk-general', 'Глава II. Понятие преступления, виды преступлений и вина', NULL, NULL, '["📌 СТАТЬЯ 2. Понятие преступления","Преступлением признаётся виновно совершённое общественно опасное деяние, запрещённое настоящим Кодексом под угрозой наказания.","Не является преступлением действие (бездействие), хотя формально и содержащее признаки деяния, предусмотренного Кодексом, но в силу малозначительности не представляющее общественной опасности.","","📌 СТАТЬЯ 2.1. Рецидив преступлений","Рецидивом преступлений признаётся совершение умышленного преступления лицом, имеющим судимость за ранее совершённое умышленное преступление. Рецидив влечёт более строгое наказание.","","📌 СТАТЬЯ 2.2. Формы вины","Виновным в преступлении признаётся лицо, совершившее деяние умышленно или по неосторожности. Деяние, совершённое только по неосторожности, признаётся преступлением лишь в случае, когда это специально предусмотрено статьёй Кодекса.","","📌 СТАТЬЯ 2.3. Преступление, совершённое умышленно","Преступлением, совершённым умышленно, признаётся деяние, совершённое с прямым или косвенным умыслом.","","Прямой умысел: лицо осознавало общественную опасность своих действий (бездействия), предвидело возможность или неизбежность наступления общественно опасных последствий и желало их наступления.","","Косвенный умысел: лицо осознавало общественную опасность своих действий (бездействия), предвидело возможность наступления общественно опасных последствий, не желало, но сознательно допускало эти последствия либо относилось к ним безразлично.","","📌 СТАТЬЯ 2.4. Преступление, совершённое по неосторожности","Преступлением, совершённым по неосторожности, признаётся деяние, совершённое по легкомыслию или небрежности.","","Легкомыслие: лицо предвидело возможность наступления общественно опасных последствий своих действий (бездействия), но без достаточных к тому оснований самонадеянно рассчитывало на предотвращение этих последствий.","","Небрежность: лицо не предвидело возможности наступления общественно опасных последствий своих действий (бездействия), хотя при необходимой внимательности и предусмотрительности должно было и могло предвидеть эти последствия.","","📌 СТАТЬЯ 2.5. Невиновное причинение вреда","Деяние признаётся совершённым невиновно, если лицо не осознавало и по обстоятельствам дела не могло осознавать общественной опасности своих действий либо не предвидело и не должно было или не могло предвидеть возможность наступления последствий.","Деяние также признаётся невиновным, если лицо, хотя и предвидело возможность наступления последствий, но не могло предотвратить их в силу несоответствия своих психофизиологических качеств требованиям экстремальных условий или нервно-психическим перегрузкам.","","📌 СТАТЬЯ 2.6. Ответственность за преступление с двумя формами вины","Если в результате совершения умышленного преступления причиняются тяжкие последствия, которые не охватывались умыслом лица, ответственность за такие последствия наступает при наличии неосторожной вины. В целом такое преступление признаётся совершённым умышленно.","","📌 СТАТЬЯ 2.7. Категории преступлений","Преступления подразделяются на следующие категории:","","• Небольшой тяжести — умышленные и неосторожные деяния, за совершение которых максимальное наказание не превышает двух лет лишения свободы.","• Средней тяжести — умышленные деяния с максимальным наказанием до трёх лет лишения свободы, и неосторожные деяния — до четырёх лет.","• Тяжкие — умышленные деяния с максимальным наказанием до четырёх лет лишения свободы, и неосторожные деяния — до пяти лет.","• Особо тяжкие — умышленные деяния, за совершение которых предусмотрено наказание в виде лишения свободы на срок свыше четырёх лет.","","Суд вправе при наличии смягчающих обстоятельств изменить категорию преступления на менее тяжкую, но не более чем на одну категорию."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('uk-general', 'Глава III. Неоконченное преступление и соучастие', NULL, NULL, '["📌 СТАТЬЯ 3. Оконченное и неоконченное преступления","Преступление признаётся оконченным, если в совершённом деянии содержатся все признаки состава преступления.","Неоконченным преступлением признаются приготовление к преступлению и покушение на преступление.","Ответственность за неоконченное преступление наступает по статье за оконченное преступление со ссылкой на статью 3.1.","","📌 СТАТЬЯ 3.1. Приготовление и покушение","Приготовление — приискание, изготовление или приспособление средств или орудий совершения преступления, приискание соучастников, сговор, иное умышленное создание условий, если преступление не было доведено до конца по не зависящим обстоятельствам.","Покушение — умышленные действия (бездействие), непосредственно направленные на совершение преступления, если преступление не было доведено до конца по не зависящим обстоятельствам.","","📌 СТАТЬЯ 3.2. Добровольный отказ от преступления","Добровольный отказ — прекращение лицом приготовления либо действий, непосредственно направленных на совершение преступления, если лицо осознавало возможность доведения до конца.","Лицо не подлежит уголовной ответственности за преступление при добровольном и окончательном отказе от его доведения до конца.","Организатор и подстрекатель не подлежат ответственности, если своевременным сообщением органам власти предотвратили доведение преступления до конца.","","📌 СТАТЬЯ 3.3. Соучастие в преступлении","Соучастием признаётся умышленное совместное участие двух или более лиц в совершении умышленного преступления.","","📌 СТАТЬЯ 3.4. Виды соучастников","Соучастниками наряду с исполнителем признаются организатор, подстрекатель и пособник.","","• Исполнитель — лицо, непосредственно совершившее преступление либо непосредственно участвовавшее в его совершении совместно с другими лицами (соисполнителями).","• Организатор — лицо, организовавшее совершение преступления или руководившее его исполнением, а равно создавшее организованную группу или преступное сообщество либо руководившее ими.","• Подстрекатель — лицо, склонившее другое лицо к совершению преступления путём уговора, подкупа, угрозы или другим способом.","• Пособник — лицо, содействовавшее совершению преступления советами, указаниями, предоставлением информации, средств или орудий, устранением препятствий, а также заранее обещавшее скрыть преступника или следы преступления.","","📌 СТАТЬЯ 3.5. Ответственность соучастников","Ответственность соучастников определяется характером и степенью фактического участия каждого в совершении преступления.","Соисполнители отвечают по статье Особенной части без ссылки на статью 3.4.","Организатор, подстрекатель и пособник несут ответственность по статье за совершенное преступление со ссылкой на статью 3.4.","","📌 СТАТЬЯ 3.6. Формы соучастия","• Группа лиц — участие двух и более исполнителей без предварительного сговора.","• Группа лиц по предварительному сговору — лица заранее договорились о совместном совершении преступления.","• Организованная группа — устойчивая группа лиц, заранее объединившихся для совершения одного или нескольких преступлений.","• Преступное сообщество — структурированная организованная группа, действующая под единым руководством, объединённая для совершения тяжких или особо тяжких преступлений.","Совершение преступления в составе группы влечёт более строгое наказание.","","📌 СТАТЬЯ 3.7. Эксцесс исполнителя","Эксцесс исполнителя — совершение исполнителем преступления, не охватывающегося умыслом других соучастников. За эксцесс исполнителя другие соучастники ответственности не несут."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('uk-general', 'Глава IV. Обстоятельства, исключающие преступность деяния', NULL, NULL, '["📌 СТАТЬЯ 4. Необходимая оборона","Не является преступлением причинение вреда посягающему лицу в состоянии необходимой обороны при защите личности и прав обороняющегося или других лиц от общественно опасного посягательства, если это посягательство было сопряжено с насилием, опасным для жизни, либо с непосредственной угрозой такого насилия.","Защита от посягательства, не сопряжённого с насилием, опасным для жизни, является правомерной, если не было допущено превышения пределов необходимой обороны.","Не являются превышением: действия обороняющегося, который вследствие неожиданности посягательства не мог объективно оценить степень и характер опасности нападения; действия, направленные на защиту себя и своей семьи от насилия либо на защиту своего имущества против лица, незаконно проникшего в жилище.","","📌 СТАТЬЯ 4.1. Причинение вреда при задержании преступника","Не является преступлением причинение вреда лицу, совершившему преступление, при его задержании для доставления органам власти, если иными средствами задержать его не представлялось возможным и не было допущено превышения необходимых для этого мер.","Превышением признаётся явное несоответствие мер характеру и степени общественной опасности совершённого преступления, когда лицу без необходимости причиняется явно чрезмерный вред.","","📌 СТАТЬЯ 4.2. Крайняя необходимость","Не является преступлением причинение вреда охраняемым законом интересам в состоянии крайней необходимости для устранения опасности, непосредственно угрожающей личности и правам данного лица или иных лиц, если эта опасность не могла быть устранена иными средствами и не было допущено превышения пределов крайней необходимости.","Превышением признаётся причинение вреда, явно не соответствующего характеру и степени угрожавшей опасности, когда был причинён вред равный или более значительный, чем предотвращённый.","","📌 СТАТЬЯ 4.3. Обоснованный риск","Не является преступлением причинение вреда охраняемым законом интересам при обоснованном риске для достижения общественно полезной цели.","Риск признаётся обоснованным, если цель не могла быть достигнута не связанными с риском действиями и лицо предприняло достаточные меры для предотвращения вреда.","Риск не признаётся обоснованным, если он заведомо был сопряжён с угрозой для жизни многих людей, с угрозой экологической катастрофы или общественного бедствия.","","📌 СТАТЬЯ 4.4. Исполнение приказа или распоряжения","Не является преступлением причинение вреда лицом, действующим во исполнение обязательных для него приказа или распоряжения. Ответственность несёт лицо, отдавшее незаконные приказ или распоряжение.","Лицо, совершившее умышленное преступление во исполнение заведомо незаконных приказа или распоряжения, несёт ответственность на общих основаниях.","","📌 СТАТЬЯ 4.5. Физическое или психическое принуждение","Не является преступлением причинение вреда в результате физического принуждения, если лицо не могло руководить своими действиями.","Вопрос об ответственности за причинение вреда в результате психического принуждения решается с учётом положений статьи 4.2 (крайняя необходимость)."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('uk-general', 'Глава V. Виды и назначение наказаний', NULL, NULL, '["📌 СТАТЬЯ 5. Виды наказаний","Видами наказаний являются: судебный штраф, уголовный штраф, лишение права занимать определённые должности, увольнение с государственной или военной службы (с лишением званий, наград и привилегий), лишение свободы на определённый срок, исправительные работы, принудительные работы.","","Судебные штрафы применяются исключительно в судебном порядке. Уголовные штрафы применяются сотрудниками LSPD, LSCSD, USSS, FIB, а также Офисом Генерального Прокурора и судом.","","В результате расследования правоохранительными органами по уголовным статьям может быть назначено только лишение свободы на определённый срок и/или уголовный штраф.","","📌 СТАТЬЯ 5.1. Исправительные работы","Исправительные работы назначаются осуждённому, имеющему или не имеющему основное место работы. Осуждённый отбывает исправительные работы по основному месту работы либо в местах, определяемых судом.","В случае злостного уклонения суд может заменить неотбытое наказание принудительными работами или лишением свободы.","","📌 СТАТЬЯ 5.1.2. Принудительные работы","Принудительные работы применяются как альтернатива лишению свободы. Если суд приходит к выводу о возможности исправления осуждённого без реального отбывания наказания, он заменяет лишение свободы принудительными работами.","В случае уклонения от отбывания принудительных работ неотбытая часть наказания заменяется лишением свободы.","","📌 СТАТЬЯ 5.2. Общие начала назначения наказания","Наказание назначается в пределах, предусмотренных соответствующей статьёй Особенной части, с учётом положений Общей части.","Суд и Офис Генерального Прокурора вправе назначить наказание до 10 лет лишения свободы за особо тяжкие преступления.","При совершении нескольких преступлений наказание назначается в пределах статьи, предусматривающей наиболее строгое наказание, либо отдельно за каждое преступление с частичным или полным сложением.","","📌 СТАТЬЯ 5.2.1. Назначение наказания за неоконченное преступление","Срок наказания за приготовление не может превышать половины максимального срока за оконченное преступление.","Срок наказания за покушение не может превышать трёх четвертей максимального срока за оконченное преступление.","","📌 СТАТЬЯ 5.3. Смягчающие обстоятельства","Смягчающими обстоятельствами признаются:","• совершение преступления в результате физического или психического принуждения либо в силу материальной, служебной или иной зависимости;","• совершение преступления при нарушении условий правомерности необходимой обороны, задержания, крайней необходимости, обоснованного риска, исполнения приказа;","• противоправность или аморальность поведения потерпевшего, явившегося поводом для преступления;","• явка с повинной, активное способствование раскрытию преступления, изобличению других соучастников;","• оказание помощи потерпевшему, добровольное возмещение ущерба, заглаживание вреда;","• совершение впервые преступления небольшой или средней тяжести вследствие случайного стечения обстоятельств.","","📌 СТАТЬЯ 5.4. Отягчающие обстоятельства","Отягчающими обстоятельствами признаются:","• совершение преступления в составе группы лиц;","• совершение преступления по мотивам политической, идеологической, расовой, национальной или религиозной ненависти или вражды;","• совершение преступления из мести за правомерные действия других лиц либо с целью скрыть другое преступление;","• совершение преступления в отношении лица в связи с осуществлением им служебной деятельности;","• совершение преступления с особой жестокостью, садизмом, издевательством, мучениями;","• совершение преступления с использованием доверия, оказанного в силу служебного положения;","• совершение преступления с использованием форменной одежды или документов представителя власти;","• совершение преступления в состоянии алкогольного или наркотического опьянения;","• рецидив преступлений;","• совершение преступления в отношении потерпевшего, находящегося в заведомо беспомощном положении;","• наступление тяжких последствий в результате совершения преступления.","","📌 СТАТЬЯ 5.5. Назначение более мягкого наказания","При наличии исключительных обстоятельств, существенно уменьшающих степень общественной опасности преступления, наказание может быть назначено ниже низшего предела или назначен более мягкий вид наказания.","","📌 СТАТЬЯ 5.6. Освобождение от ответственности в связи с примирением сторон","Лицо, впервые совершившее преступление, может быть освобождено судом от уголовной ответственности, если оно примирилось с потерпевшим и загладило причинённый вред.","Лицо, впервые совершившее преступление, может быть освобождено от ответственности с назначением судебного штрафа от 10 000$ и/или исправительных работ.","","📌 СТАТЬЯ 5.7. Сроки давности","Лицо освобождается от уголовной ответственности, если со дня совершения преступления прошло 25 дней (25 лет IC).","По особо тяжким преступлениям (убийство, похищение, терроризм, взятки и др.) сроки давности не применяются.","К лицам, находящимся в федеральном розыске, сроки давности не применяются.","Сроки давности исчисляются со дня совершения преступления до момента вступления приговора в законную силу.","","📌 СТАТЬЯ 5.8. Судимость","При аресте по статьям с ★★★★ и более ставится отметка о судимости.","Погашение или снятие судимости аннулирует все правовые последствия, связанные с судимостью.","При назначении уголовного штрафа судимость не возникает.","","📌 СТАТЬЯ 5.9. Добровольная сдача предметов","Лицо, добровольно сдавшее предметы, указанные в статьях 12.8, 12.8.1, 13.1, 13.2 (оружие, наркотики), освобождается от уголовной ответственности по соответствующей статье.","Не признаётся добровольной сдачей изъятие при задержании или в ходе следственных действий.","","📌 СТАТЬЯ 5.10. Залог","Лицо, заключённое под стражу по статьям, не влекущим судимость, может быть освобождено под залог. Залог устанавливается в соотношении 1 год лишения свободы = 25 000$."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('pk', '👥 Статья 18. Субъекты задержания', NULL, NULL, '["В процессе задержания участвуют:","","а) Сотрудник(и) правоохранительных органов при исполнении, которые осуществляют задержание и/или оказывают содействие","","б) Задержанный, в отношении которого проводится задержание","","в) Один прокурор — согласно принятому вызову или по собственной инициативе","","г) Один адвокат — в случае необходимости оказания юридической помощи. Адвокат имеет право задать задержанному краткий вопрос о наличии такой необходимости","","д) Руководство задержанного сотрудника государственных органов (в соответствии со ст.19 ч.1)","","е) До двух сотрудников USSS, если один из субъектов задержания обладает статусом неприкосновенности","","ж) Один сотрудник IB для проведения надзора","","з) Сотрудники Detective Bureau (LSPD/LSCSD) и Criminal Investigation Department (FIB) с согласия инициатора задержания имеют право провести допрос задержанному. Могут запросить информацию о статьях и получить разрешение на допрос-передачу. В случае отказа обязаны покинуть место","","и) Один представитель руководства сотрудника(ов), осуществляющих задержание (руководитель организации или его заместитель)","","к) До трёх юристов (стажеров) Коллегии адвокатов в сопровождении адвоката, исключительно для наблюдения и прохождения практики","","══════════════════════════════════════════════════════════════════","","⚠️ Примечания:","- В процессе может участвовать лишь один адвокат и(или) прокурор","- Не допускается замена прокурора, за исключением особых обстоятельств","- Юристы-стажеры не имеют права вмешиваться в процесс, подавать ходатайства или перебивать участников. При нарушении порядка — могут быть удалены"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('pk', '🚔 Статья 17. Порядок задержания правомочным лицом', NULL, NULL, '["Задержание лица при ведении следствия производится в следующей последовательности:","","1️⃣ Надеть наручники на подозреваемого","","2️⃣ Предъявить документ, удостоверяющий служебное положение (удостоверение, нашивку, жетон, бейдж)","","3️⃣ На усмотрение сотрудника — провести первичный обыск","   Первичный обыск производится для идентификации колющих, режущих орудий, огнестрельного оружия, наркотических веществ, взрывчатых элементов. Разрешается смотреть документы задержанного","","4️⃣ Разъяснить квалификацию правонарушения и зачитать правило Миранды","","5️⃣ Провести идентификацию личности задержанного, проверку на предмет наличия в базе федерального розыска и принадлежности к государственным органам","","6️⃣ Доставить подозреваемого в полицейский участок, департамент шерифа, штаб FIB или иное место следствия","","7️⃣ Реализовать права задержанного. В случае, если задержанный является госслужащим или сотрудником Weazel News — уведомить уполномоченные органы (ст.19)","","8️⃣ Произвести следственные действия при необходимости (допрос, экспертиза и т.д.)","","══════════════════════════════════════════════════════════════════","","📢 ПРАВИЛО МИРАНДЫ:","«Вы имеете право хранить молчание. Всё, что вы скажете, может и будет использовано против вас в суде. Вы имеете право на один телефонный звонок. Вы имеете право на адвоката. Если вам нужен адвокат, он будет для вас запрошен. Вы понимаете свои права?»","","Правило зачитывается дважды (если первый раз не понял). После второго раза уведомляется, что правило зачитываться более не будет.","","⚠️ Порядок действий может быть изменён на усмотрение сотрудника в пунктах 3 и 4, а также в пунктах 3,4,5 при задержании по ордеру."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('pk', '📋 Статья 16. Основания для задержания подозреваемого', NULL, NULL, '["Лицо может быть задержано по подозрению в совершении правонарушения при наличии хотя бы одного из оснований:","","а) Лицо застигнуто в момент совершения правонарушения или непосредственно после его окончания","","б) На подозреваемом или его одежде, при нём или в его жилище обнаружены явные следы правонарушения","","в) 3 и более свидетеля указывают на данное лицо","   ⚠️ Свидетелями не могут быть родственники, знакомые, коллеги и другие заинтересованные лица","","г) Фото или видеофиксация совершения правонарушения этим лицом","","д) Ордер, изданный в установленном законом порядке, указывающий на необходимость задержания","","е) Требование Губернатора, Генерального прокурора или его заместителей","","ж) Ориентировка на транспортное средство или данное лицо","","з) Лицо находится в боло-розыске"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('pk', '🎭 Статья 16 ч.3. Требование снять маску/капюшон', NULL, NULL, '["Если лицо находится в маске, капюшоне, шлеме либо ином предмете, скрывающем лицо, уполномоченное лицо имеет право выдвинуть законное требование о снятии такого предмета, а также предъявить документы (удостоверение госслужащего или ID-card) при наличии объективных оснований:","","• Нахождение на территории государственных учреждений или охраняемых объектов","• Проведение массовых мероприятий","• Наличие оснований полагать, что гражданин находится в розыске (соответствие внешних признаков ориентировке, нахождение в непосредственной близости от места преступления)","• При совершении гражданином правонарушения","","⚠️ Отказ выполнить законное требование является основанием для задержания и принудительного установления личности."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('pk', '👮 Статья 15. Уполномоченные органы на задержание', NULL, NULL, '["Уполномоченными органами на проведение задержания при ведении следствия признаются:","","• Полицейский департамент Лос-Сантоса (LSPD)","• Департамент шерифа округа Блейн (LSCSD)","• Федеральное расследовательское бюро (FIB)","","С обязательной передачей вышеуказанным органам могут проводить задержание:","","• Региональное отделение Секретной службы (USSS)","• Национальная гвардия штата (SANG)","• Weazel News (в пределах полномочий, установленных законом)","","На основании ордера правительства или решения суда проводить задержание могут: LSPD, LSCSD, FIB, USSS."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('pk', '💰 Статья 21. Порядок исполнения штрафных санкций', NULL, NULL, '["При назначении административного или уголовного штрафа лицо обязано произвести его оплату.","","Если у лица отсутствует при себе достаточная сумма денежных средств, сотрудник, вынесший решение о штрафе, обязан:","","а) сопроводить гражданина к ближайшему банкомату или банковскому отделению для снятия наличных средств с личного счёта","б) удостовериться, что гражданин произвёл оплату штрафа, и зафиксировать факт оплаты"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('pk', '📞 Статья 22. Права задерживаемого', NULL, NULL, '["Подозреваемый имеет следующие права:","","а) Право на один телефонный звонок в присутствии сотрудника (до начала ареста, длительность не более 3 минут).","   ⚠️ Звонок предназначен исключительно для связи с частным адвокатом, с которым заключён устный договор.","","б) Право на адвоката. Если в течение 3 минут с момента обращения нет ответа — право считается реализованным.","","в) Право сохранять молчание.","","г) Право возбуждать ходатайства и заявлять отводы.","","д) Право на конфиденциальную встречу с адвокатом длительностью не более 10 минут.","","е) Право требовать, чтобы сотрудник разъяснил причину задержания и квалификацию правонарушения.","","ж) Право на гуманное обращение, запрещены пытки, насилие и унижение человеческого достоинства."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('pk', '⏱️ Статья 20. Основания освобождения подозреваемого', NULL, NULL, '["Подозреваемый подлежит освобождению, если:","","а) не подтвердилось подозрение в совершении правонарушения","б) за нарушение не предусмотрено наказание в виде лишения свободы","в) задержание произведено с нарушением ч.2 ст.16","г) прошло больше 1 часа с момента задержания и не избрана мера наказания","д) подозреваемый обладает статусом неприкосновенности (кроме угрозы жизни окружающих)","","Течение срока (п.г) приостанавливается при: проведении допроса/экспертизы, вызове адвоката/прокурора/руководства, обыске имущества, просмотре видеофиксации (максимум 10 минут)."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('pk', '🏛️ Статья 19. Уведомление о задержании госслужащего', NULL, NULL, '["Если задержанный является государственным служащим, сотрудником Weazel News или частным адвокатом, сотрудник обязан вызвать руководство задержанного и сотрудника ОГП.","","Время задержания замораживается:","- На 5 минут для ожидания ответа руководства + до 10 минут для его прибытия","- На 15 минут для ожидания ответа прокурора, до его приезда — при положительном ответе","","⚠️ Если прокурор не может прибыть — задержанный подлежит освобождению, сотрудники обязаны обратиться в ОГП в течение часа.","","⚠️ Если руководство не может прибыть — прокурор или лицо, производящее задержание, обязано уведомить руководство о задержании подчинённого."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('pk', '💰 Статья 5. Виды наказаний (УК/АК)', NULL, NULL, '["Видами наказаний являются:","","а) Судебный штраф","б) Уголовный штраф","в) Лишение права занимать определённые должности","г) Увольнение с государственной или военной службы (с лишением званий, наград и привилегий)","д) Лишение свободы на определённый срок","е) Исправительные работы","ё) Принудительные работы","","Судебные штрафы — только в судебном порядке.","Уголовные штрафы — применяются сотрудниками LSPD, LSCSD, USSS, FIB, ОГП и судом.","В результате расследования правоохранительными органами может быть назначено только лишение свободы и/или уголовный штраф."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('pk', '⚠️ Статья 5.7. Сроки давности', NULL, NULL, '["Лицо освобождается от уголовной ответственности, если со дня совершения преступления прошло 25 дней.","","❌ Сроки давности НЕ применяются к лицам, совершившим преступления по главе 14, статьям: 6.1 ч.2, 6.2 ч.1, 6.3, 7.1, 8.1, 12.1, 12.1.1, 12.3, 12.4, 12.5, 15.1, 15.1.1, 16.1, 16.2, 16.4, 16.10, 17.1 УК, а также к лицам, находящимся в федеральном розыске.","","Сотрудники LSPD/LSCSD/FIB/USSS могут установить боло-розыск от ★ до ★★★★★."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('pk', '💰 Статья 5.10. Залог', NULL, NULL, '["Лицо, заключённое под стражу по статьям, не влекущим судимость, может быть освобождено под залог.","💰 Залог = 25 000$ × количество лет (звёзд)","","Пример:","• 1 звезда = 25 000$","• 2 звезды = 50 000$","• 5 звёзд = 125 000$"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('pk', '🔍 Статья 27. Порядок ареста', NULL, NULL, '["Порядок ареста проводится строго в следующем порядке:","","а) Совершить вторичный обыск","б) Изъять все нелегальные предметы у гражданина, подвергнутого аресту","в) Установить соответствующий уровень боло-розыска в соотношении 1 год = 1 уровень","г) Разъяснить задержанному причину ареста","д) Поместить в КПЗ на срок, установленный уголовным кодексом","","⚠️ При вторичном обыске изымаются ВСЕ нелегальные предметы, а также колющие, режущие предметы, огнестрельное оружие, спецсредства, боеприпасы — независимо от законности хранения.","","Исключение: не изымаются дефибриллятор и эпинефрин без гос.номера при наличии действующей лицензии парамедика."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('pk', '🔍 Статья 29-30. Обыск и осмотр', NULL, NULL, '["Личный обыск — только во время задержания и (или) ареста, либо при подозрении на запрещённые предметы при нахождении на территории государственного органа.","","Граждане могут быть подвергнуты личному досмотру:","• При пересечении КПП мест дислокации SANG","• При посещении Капитолия и зала Суда (по требованию USSS)","   ⚠️ USSS не вправе требовать досмотр у госслужащих при исполнении и неприкосновенных лиц","","Осмотр транспортного средства — визуальное обследование при ориентировке, иной информации об использовании ТС в противоправных целях.","","Обыск транспортного средства — со вскрытием, при выявлении нарушения УК."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('pk', '🔫 Статья 37. Стадии применения силы', NULL, NULL, '["Каждый госслужащий обязан опираться на стадии применения силы. Все стадии соблюдаются в строгом иерархическом порядке от первой до пятой.","","1️⃣ ПЕРВАЯ СТАДИЯ — Присутствие","   Присутствие сотрудника при исполнении. В некоторых ситуациях достаточно для прекращения правонарушения.","","2️⃣ ВТОРАЯ СТАДИЯ — Приказ","   Требования должны быть исполнимыми и законными, иметь целью охрану общественного порядка.","","3️⃣ ТРЕТЬЯ СТАДИЯ — Применение физической силы","   Заламывание рук, удержание на месте с силой, дубинки, слезоточивые аэрозоли.","","4️⃣ ЧЕТВЁРТАЯ СТАДИЯ — Применение специальных средств","   Наручники, электрошоковые устройства, резиновые пули. Запрещены предупредительные выстрелы/удары.","","5️⃣ ПЯТАЯ СТАДИЯ — Применение огнестрельного оружия","   Огнестрельное оружие, автомобиль, подручные средства. Предупредительные выстрелы ЗАПРЕЩЕНЫ.","   Запрещено применять при значительном скоплении граждан, если могут пострадать случайные лица.","","❌ ИСКЛЮЧЕНИЯ (можно сразу переходить к 4-й стадии):","• Когда сотрудник стал свидетелем правонарушения","• При угрозе опасности для сотрудников или гражданских лиц","• При большом скоплении вооружённых людей (можно сразу 5-ю стадию)"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('pk', '📹 Статья 32-33. Фото и видеофиксация', NULL, NULL, '["Государственный служащий или его напарник обязаны вести видеофиксацию:","• Во время пресечения правонарушения","• Во время проведения процессуальных действий","","❌ Исключения (можно приостановить запись):","• Во время реализации права задержанного на адвоката","• Во время разбирательства с ОГП и/или руководством задержанного (если задержанный — госслужащий)","","Срок хранения видеофиксации — 72 часа с момента записи.","","⚠️ Если в отношении госслужащего подано исковое заявление или обращение в ОГП, он не имеет права удалять записи или иные доказательства на время доследственной проверки и расследования."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('pk', '📋 Статья 50. Письменная отчетность', NULL, NULL, '["Дело должно вестись с письменной отчетностью в случаях, предусмотренных внутренним регламентом, или при необходимости передачи дела в суд.","","Процессуальные документы могут быть выполнены:","• Типографским способом","• Электронным способом","• Написаны от руки (при отсутствии бланков)"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('pk', '🔄 Статья 35-36. Компетенция и подследственность', NULL, NULL, '["Компетенция — установленный законом объём прав, обязанностей и полномочий органа или должностного лица.","","[Региональная] — LSPD / LSCSD","[Федеральная] — FIB / USSS","[Финансовая] — USSS","[Военная] — SANG","","Сотрудники региональных органов могут отрабатывать федеральные статьи ТОЛЬКО по одобрению запроса старшим составом FIB.","Сотрудники федеральных органов могут отрабатывать региональные статьи ТОЛЬКО по одобрению запроса старшим составом LSPD/LSCSD.","","Сотрудники ОГП имеют право на проведение следственных действий на всей территории штата вне зависимости от категории статьи в рамках своих полномочий.","⚠️ Сотрудникам ОГП недопустимо использование наручников и иных спецсредств, а также самостоятельно инициировать задержание с применением силы."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('pk', '📋 Статья 41-43. Ходатайства и жалобы', NULL, NULL, '["Право заявить ходатайство имеют: подозреваемый, обвиняемый, защитник, потерпевший, эксперт, гражданский истец/ответчик и их представители.","","Ходатайство может быть заявлено в любой момент производства по делу.","","Ходатайство подлежит рассмотрению непосредственно после его заявления, но не позднее 3 суток.","","Об удовлетворении либо отказе выносится постановление.","","Действия (бездействие) и решения следователя, прокурора и суда могут быть обжалованы участниками судопроизводства."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('pk', '🔍 Статья 57. Допрос', NULL, NULL, '["Свидетель, потерпевший, обвиняемый, подозреваемый вызывается на допрос повесткой с указанием места, даты и времени.","","Должностное лицо обязано уведомить допрашиваемого о месте и времени проведения допроса не позднее 12 часов до его проведения (если не оговорено иное по согласию сторон).","","Если допрашиваемый явился с адвокатом, адвокат присутствует при допросе и пользуется правами.","","Следователь или прокурор обязаны обеспечить аудио- и (или) видеозапись допроса.","","⏱️ Допрос не может длиться более 1 часа. Допрос по повестке не может проводиться в ночное время (22:00 - 06:00)."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('pk', '⚖️ Статья 66-67. Уголовное производство', NULL, NULL, '["Уголовное производство имеет своим назначением:","1) Защиту прав и законных интересов потерпевших","2) Защиту личности от незаконного и необоснованного обвинения","3) Уголовное преследование и назначение справедливого наказания","","Никто не может быть признан виновным и подвергнут уголовному наказанию иначе как в порядке, установленном законодательством.","","Лицо, которому назначено наказание, не может быть лишено права на рассмотрение его дела в судебных органах и права обжалования решений."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('pk', '🚫 Статья 78.1-78.2. Обстоятельства, исключающие участие в производстве по делу (отводы)', NULL, NULL, '["📌 Статья 78.1. Обстоятельства, исключающие участие в производстве по уголовному делу","","Прокурор, следователь не может участвовать в производстве по уголовному делу, если он:","1) является потерпевшим по делам частного и частно-публичного обвинения, гражданским истцом, гражданским ответчиком по данному уголовному делу;","2) участвовал в качестве присяжного заседателя, эксперта, специалиста, переводчика, понятого, помощника судьи, секретаря судебного заседания, защитника, законного представителя подозреваемого, обвиняемого, представителя потерпевшего, гражданского истца или гражданского ответчика;","3) является близким родственником или родственником любого из участников производства по данному уголовному делу.","","Лица, указанные выше, не могут участвовать в производстве по уголовному делу также в случаях, если имеются иные обстоятельства, дающие основание полагать, что они лично, прямо или косвенно, заинтересованы в исходе данного уголовного дела.","","📌 Статья 78.2. Недопустимость участия в производстве по уголовному делу лиц, подлежащих отводу","","При наличии оснований для отвода прокурор, следователь обязаны устраниться от участия в производстве по уголовному делу.","","Если они не устранились, отвод им может быть заявлен подозреваемым, обвиняемым, его законным представителем, защитником, а также государственным обвинителем, потерпевшим, гражданским истцом, гражданским ответчиком или их представителями.","","В случае отказа в удовлетворении заявления об отводе подача повторного заявления тем же лицом и по тем же основаниям не допускается.","","Решение об отказе в удовлетворении заявления об отводе, принятое в ходе досудебного производства, не является препятствием для последующей подачи заявления об отводе в ходе судебного производства.","","Вопрос об отводе следователя, прокурора разрешается ими же немедленно. В случае несогласия с решением заявитель вправе обратиться с жалобой в суд либо в Офис Генерального Прокурора."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('pk', '📖 Статья 79. Терминология (основные понятия)', NULL, NULL, '["Алиби — нахождение подозреваемого или обвиняемого в момент совершения правонарушения в другом месте;","","Апелляционная инстанция — суд второй инстанции, рассматривающий в апелляционном порядке дела по жалобам, приговорам, определениям и постановлениям суда;","","Близкие лица — иные, за исключением близких родственников и родственников, лица, состоящие в свойстве с потерпевшим, свидетелем, а также лица, жизнь, здоровье и благополучие которых дороги потерпевшему, свидетелю в силу сложившихся личных отношений;","","Близкие родственники — супруг, супруга, родители, дети, усыновители, усыновленные, родные братья и родные сестры, дедушка, бабушка, внуки;","","Вердикт — решение о виновности или невиновности подсудимого, вынесенное коллегией присяжных заседателей;","","Государственный обвинитель — поддерживающее от имени государства обвинение в суде по делу должностное лицо Офиса Генерального прокурора;","","Досудебное производство — судопроизводство с момента получения сообщения о правонарушении до направления прокурором дела в суд;","","Жилище — индивидуальный жилой дом, жилое помещение, используемое для постоянного или временного проживания, а равно иное помещение или строение, используемое для временного проживания;","","Законная сила — обязательность и непреложность решения, акта или нормы права. Решение, вступившее в законную силу, не может быть обжаловано;","","Задержание — мера процессуального принуждения, применяемая сотрудниками силовых структур на срок не более 1 часа;","","Осмотр — процесс визуального изучения места происшествия, местности, лиц, жилища, иных помещений, предметов и документов. При осмотре не допускается физическое воздействие;","","Досмотр — обследование вещей без нарушения их конструктивной целостности в целях обнаружения потенциально опасных предметов. Лицо может отказаться от досмотра с условием выдворения с территории;","","Обыск — обследование помещений либо лиц (личный обыск) в целях обнаружения предметов, имеющих значение для производства;","","Кассационная инстанция — суд третьей инстанции, рассматривающий дела по жалобам на решения апелляционного суда;","","Момент фактического задержания — момент фактического лишения свободы передвижения лица;","","Непричастность — неустановленная либо установленная непричастность лица к совершению правонарушения;","","Ночное время — промежуток времени с 22 до 6 часов по местному времени;","","Обвинение — утверждение о совершении определённым лицом деяния, запрещенного УК или АК, выдвинутое в установленном порядке;","","Определение — любое решение, вынесенное судами первой и апелляционной инстанций, за исключением приговора;","","Постановление — любое решение, за исключением приговора, вынесенное судьей; решение прокурора, следователя;","","Председательствующий — судья, который руководит судебным заседанием;","","Приговор — решение о невиновности или виновности подсудимого, вынесенное судом первой или апелляционной инстанции;","","Присяжный заседатель — лицо, привлеченное для участия в судебном разбирательстве и вынесения вердикта;","","Процессуальное действие — следственное, судебное или иное действие, предусмотренное настоящим Кодексом;","","Свидетельский иммунитет — право лица не давать показания против себя и своих близких родственников;","","Следователь — служащий правоохранительных органов, уполномоченный осуществлять следствие;","","Судебное заседание — процессуальная форма осуществления правосудия;","","Суд первой инстанции — суд, рассматривающий дело по существу;","","Суд второй инстанции — суд апелляционной инстанции;","","Суд третьей инстанции — суд кассационной инстанции;","","Внепроцессуальное обращение — обращение в письменной или устной форме не являющихся участниками судебного разбирательства лиц;","","Приказ — официальное распоряжение руководителя, командира или начальника, отданное в пределах его должностных полномочий;","","Прокурор — Генеральный прокурор, его заместители, прокуроры, а также иные должностные лица ОГП, наделенные процессуальными полномочиями."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('gov-rules', '1. Общее положение', NULL, NULL, '["1.1.1 Сотрудникам гос. структур запрещено любые криминальные действия без написанной и одобренной РП ситуации на форуме. | WARN","Пояснение: РП ситуация должна содержать полную завязку и знакомство с криминальным миром, начиная от знакомств с определенными людьми, заканчивая дальнейшим продвижением в криминальный мир и сотрудничеством.","Исключение: р. 11, п. 4.","","1.1.2 Руководящему составу запрещено иметь какую-либо криминальную деятельность, включая взятки. | WARN","Пояснение: к руководящему составу относятся: лидер, заместитель лидера, начальники отделов и заместители начальников отдела.","Исключение: старшим рангам разрешено брать крупные взятки с написанием и одобрением РП ситуации.","","1.1.3 Сумма взятки не должна превышать 100.000$ (взятка должна быть исключительно деньгами), для получения более крупных сумм необходимо написание криминальной РП ситуации. | WARN","","1.2.1 Запрещено продавать / сливать гос. имущество / казну. | Demorgan 45-90 минут / Ban 3-30 дней / Hardban 7-30 / PermBan, а так же аннулирование сделки / обнуление персонажа","Примечание: при продаже слитого имущества администрация вправе выдать блокировку аккаунта до возврата денежных средств.","Исключение: одобренная РП ситуация на форуме; одобрение главного куратора; гос.трейд, одобренный администрацией.","","1.2.2 Запрещено продавать или оставлять себе предметы, которые были получены после криминальных событий. | Demorgan 35-90 минут / Ban 3-15 дней / HardBan до изъятия","Примечание: все предметы, полученные по итогам перестрелки/операции, должны быть положены на склад / утилизированы, так как являются вещдоками.","","1.2.3 Сотрудникам гос. структур разрешено хранить предметы, принадлежащие любой гос. структуре, исключительно на складе своей фракции, в транспорте своей фракции и(или) в своём инвентаре. | Demorgan 35-90 минут / Ban 3-30 дней + Изъятие / HardBan до изъятия","","1.3 Запрещено изъятие адвокатских / обычных лицензий без весомой IC причины. | WARN / Ban 3-15 дней","Примечание: лидер фракции несет полную ответственность за настройку матрицы фракции, в случае массовых изъятий и нарушений лидер получает выговор / снятие.","Пример: в случае нарушения игроком статьи не связанной с оружием, стрельбой и т.п. изымать лицензию на оружие.","","1.4 Запрещено оставлять себе оружие / спец. средства после увольнения / перевода / WARN''a / BAN''a. | Demorgan 35-90 минут / Ban 3-15 дней / HardBan 3-15 дней / HardBan до изъятия","Примечание: в случае Ban''a, Warn''a, увольнения, вы можете сдать вещи администратору через обращение (F2-Обращения либо /report).","","1.5 Запрещено принимать во фракцию игроков, которые имеют активный ЧС государственных организаций. | Demorgan 90 минут / WARN","","1.6 Изъятие нелегальных предметов производится исключительно через функционал сервера. | Demorgan 35 минут / WARN","","1.7 Запрещено использование дронов не по назначению. | WARN","Пояснение: использование дронов с целью личных развлечений, использование с целью шуткой над кем-либо, подглядыванием за кем-либо и т.д.","","1.8 Все права, а так же статьи, которые нарушил игрок, должны быть озвучены в голосовой чат. | Demorgan 30 минут / WARN / Ban 3-7 дней","Пример: миранда и т.п.","Примечание: озвучивание должно быть в полном объеме, четкое, в умеренном темпе и понятное для игрока(-ов).","Исключение: в случае использовании игроком режима ''Я не слышу'' / ''Я без звука'' обязательна отыгровка в текстовый чат.","","1.9 При просьбе вызова адвоката от задержанного необходимо реализовать его право на защиту. | WARN","Примечание: игроку должна быть предоставлена возможность воспользоваться приложением ''Адвокаты''.","Исключение: если игрок изначально отказался от адвоката; задержание по ордеру на арест/иску; игрок игнорирует вопрос о запросе адвоката.","","1.10.1 Запрещено первым оскорблять, провоцировать, использовать унизительные анимации, а также грубо выражаться в присутствии задержанного или посторонних граждан. | Demorgan 50-100 минут / WARN","Примечание: сотрудники могут грубо выражаться в стрессовых ситуациях (перестрелки, криминальные действия).","","1.10.2 В функциональных зеленых зонах запрещена модель поведения не соответствующая модели поведения государственного сотрудника. | Demorgan 20-80 минут / WARN / Ban 2-5 дней","Пример: получение взяток, неформальное общение, грубое общение и т.п.","","1.11 Запрещена выдача / изъятие военных билетов без весомой IC причины. | HardBan 15-30 дней / HardBan до изъятия / PermBan","Исключение: одобрение главного куратора.","","1.12 Премирование государственных фракций и их участников происходит исключительно через функционал финансирования. | Выговор лидеру","Исключение: одобрение главного куратора.","","1.13 Сотрудникам государственной организации запрещено повышать более чем на 1 ранг в сутки. | WARN / Ban 3 дня / Выговор лидеру + понижение игрока до прежнего ранга","Исключение: одобрение главного куратора; перевод с другой государственной организации; восстановление в должности; решение суда.","","1.14 Сотрудник государственной организации может быть арестован / посажен в КПЗ только при выявлении нарушения от прокурора, принявшего вызов на задержание. | WARN","Исключение: решение суда, ордер и т.п.","","1.15 Запрещено повышать игрока без отчета о проделанной работе. | Ban 3-15 дней / HardBan 5-10 дней / Выговор лидеру + понижение игрока","Примечание: отчет должен соответствовать установленной во фракции системе повышений.","","1.16 Запрещено использовать материал для кейс-файлов, делопроизводств и т.п., который был получен без использования функциональной боди-камеры.","Исключение: внедрение / работа под прикрытием / снятие записей с камер отделений государственных структур.","","1.17 Запрещено изымать предметы у игрока не имея причин. | Hardban 15-30 дней / PermBan + Обнуление аккаунта","","1.18 Игрокам государственных структур запрещено использование вещей не входящих во фракционный гардероб, а также нарушение общего внешнего вида. | Demorgan 35-90 минут / WARN","Пример: неестественный цвет волос, неформальные прически, татуировки на лице/шее, ношение ушек/рогов/хвостов, ярких скинов на бронежилеты и т.д.","Исключение: работа под прикрытием.","","1.19 Запрещено использование фракционного склада вне фракционных мероприятий / процессов. | Ban 10-30 дней / HardBan 15-30 дней","Пример: стычки за тайники с целью получения наград, перестрелки вне рабочее время и т.п.","","1.20 Запрещено намеренное злоупотребление функционалом государственных структур. | WARN / Ban 7-15 дней / HardBan 10-30 дней / PermBan","Под злоупотребление попадает: задержание за маску; выдача 5 звезд за мелкое нарушение; необоснованная выдача судимости; намеренный срыв игрового процесса обычным игрокам и т.п.","","1.21 Максимально допустимый срок посадки в КПЗ за 1 звезду - до 10 минут. | WARN","Пояснение: максимальный срок для игрока, который имеет 5 звезд - 50 минут.","Исключение: решение суда, ордер, террористический акт.","","1.22.1 Номер опознавательного знака игроков из государственных фракций приравнивается к его статическому ID. | Demorgan 10 минут","Пояснение: опознавательный знак должен быть надет на игрового персонажа и виден при любых условиях (только для FIB, LSPD, LSCSD).","","1.22.2 Сотрудники государственных структур обязаны носить и предоставлять удостоверение, при требовании игрока(-ов). | Demorgan 15 минут","","1.23.1 Запрещено действовать вопреки решений ордеров, исков, прокурора и суда. | Ban 5-15 дней / Hardban 5-15 дней","","1.23.2 Прокурору и судьям запрещено выносить заведомо неверные, очевидно нарушающие РП логику решения. | Ban 10-15 дней / HardBan 10-30 дней / PermBan","","1.24 Запрещено намеренно затягивать процесс задержания. | Demorgan 35 минут / WARN"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('gov-rules', '2. Взаимодействие государственных организаций', NULL, NULL, '["2.1 Все государственные организации подчиняются Правительству.","","2.2.1 Правительство может быть свергнуто государственным переворотом путем написания кейс-файла и внутриигровой RP ситуации, при участии минимум двух силовых государственных структур, с одобрения Главного куратора гос. фракций, ГА.","","2.2.2 Правительство может быть свергнуто общим гражданским переворотом с участием минимум 150 человек.","Примечание: условия, требования и т.п. должны быть адекватными и выполнимыми.","","2.3 Любые внутренние инструкции, регламенты работы, отделы, услуги и т.п. должны быть утверждены Правительством и/или куратором фракции. | Выговор лидеру","","2.4 Перевод должен быть одобрен со стороны двух лидеров, либо их заместителей. | WARN / Выговор лидеру + увольнение игрока","Исключение: перевод может быть одобрен со стороны губернатора.","","2.5 Запрещено намеренно повышать игроков с целью дальнейшего его перевода в другую фракцию. | WARN / Выговор лидеру + понижение игрока на 1 ранг","","2.6 Запрещено при переводе устанавливать ранг выше, чем он был в предыдущей фракции. | WARN / Выговор лидеру + понижение игрока"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('gov-rules', '3. Government', NULL, NULL, '["3.1 Government - высший коллегиальный исполнительный орган государственного управления и государственной власти. | Demorgan 15-90 минут / WARN / Выговор лидеру / Снятие","","Задачи и обязанности Government:","- Проводить проверки государственных организаций (не более 1 в неделю на одну организацию).","- Законодательная власть обязана разработать и обеспечивать актуальность законодательной базы.","- Расходовать бюджет государственной казны только в интересах государства.","- Правительство вправе урезать премии гос.структурам при наличии веской IC причины.","- Уполномоченным сотрудникам правительства запрещено игнорировать любые правонарушения со стороны сотрудников гос.структур.","- Любой актуальный ордер / указ должен быть выложен на форум.","- Сотрудники прокуратуры и правительства уполномочены снимать розыск с игроков при его ошибочной выдаче.","- Выдача адвокатских лицензий, поддержание общедоступности реализации прав задержанного.","","3.2 Цена регистрации предприятий не может превышать 250.000$ игровой валюты. | Выговор лидеру","","3.3 Запрещена выдача адвокатских лицензий выше функциональной стоимости. | Demorgan 100 минут"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('gov-rules', '4. United States Secret Service (USSS)', NULL, NULL, '["4.1 USSS подчиняется исключительно правительству, её регламентам и уставам.","","4.2 USSS - секретная спец. служба, главная задача которой обеспечение правопорядка на территории мэрии и сопровождение первых лиц. | Demorgan 15-90 минут","","Задачи и обязанности USSS:","- Проводить проверки на выявление нарушений от сотрудников EMS, LSPD, LSCSD, Weazel News, SANG.","- Предотвращать чрезвычайные ситуации в Лос-Сантосе (теракты, ограбления банков, массовые беспорядки).","- USSS запрещено патрулирование вне территории мэрии.","Исключение: кортеж, перевозка первых лиц, теракты, ограбления банков и бизнесов, судебные дела.","- Поддержание порядка на территории мэрии, обеспечение безопасности первых лиц.","","4.3 USSS запрещено арестовывать игроков, при задержании необходимо передать сотрудникам LSPD/LSCSD/FIB. | Demorgan 50-90 минут / WARN","Исключение: задержание по ордеру и/или иску."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('gov-rules', '5. Federal Investigation Bureau (FIB)', NULL, NULL, '["5.1 Сотрудники FIB подчиняются министру юстиции и губернатору.","","5.2 FIB - федеральная правоохранительная структура, орган внутренней разведки, контрразведки и антитеррористической деятельности. | Demorgan 10-90 минут / WARN / Выговор","","Задачи и обязанности FIB:","- Осуществлять контрольную деятельность над государственными структурами.","- Слежка за исполнением и обработкой вызовов от обычных игроков в LSPD / LSCSD.","- Формирование кейс-файлов.","- Реагирование на нарушение федерального характера.","- Отработка по региональным нарушениям при запросе от старшего состава LSPD / LSCSD."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('gov-rules', '6. LSPD / LSCSD', NULL, NULL, '["6.1 Сотрудники LSPD / LSCSD подчиняются мэру, министерству юстиции, губернатору.","","6.2 LSPD / LSCSD - региональная правоохранительная структура. | Demorgan 15-90 минут / Выговор лидеру","","Задачи и обязанности:","- Патрулирование территории муниципального округа.","- Реакция на вызовы (запрещено игнорирование функциональных вызовов).","- Обработка обращений граждан.","- Реагирование на происшествия регионального характера.","- Сбор и передача информации для кейс-файлов сотрудникам FIB.","- Отработка федеральных нарушений при запросе от старшего состава FIB.","","6.3 Сотрудникам LSPD / LSCSD необходимо обрабатывать обращения граждан не позднее 48 часов с момента подачи. | Выговор лидеру"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('gov-rules', '7. SA National Guard (SANG)', NULL, NULL, '["7.1 Национальная гвардия имеет право задерживать граждан за противоправные действия только на территории Форта-Занкудо, острова Кайо-Перико, либо в случае нарушений в отношении сотрудников SANG. | Demorgan 50-90 минут / WARN","Исключение: военные преступления, военное положение, режим ЧС.","","7.2 Сотрудникам SANG запрещено находиться на территории Гетто без веских причин. | Demorgan 15-35 минут","Исключение: с 23:00 до 08:00 сотрудники SANG могут находиться на территории Гетто без запроса.","","7.3 Территория SANG начинается после КПП, вся территория до КПП свободна для посещения граждан."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('gov-rules', '8. Общее положение силовых структур', NULL, NULL, '["8.1 Сотрудниками силовых структур являются: LSPD, LSCSD, National Guard, FIB, USSS.","","8.2 Сотрудникам силовых структур запрещено задерживать игрока который был убит в процессе задержания и находится в больнице. | WARN","","8.3.1 Сотрудники силовых структур обязаны патрулировать, проводить задержание / выезжать на вызовы только на фракционном транспорте. | Demorgan 35 минут","Исключение: детективы и переговорщики; AirDrop.","","8.3.2 Запрещено выезжать на ограбления в составе менее 3-х человек. | Demorgan 35 минут","Исключение: детективы, переговорщики.","","8.4 При задержании / выдаче розыска / аресте / изъятии лицензии / обыске игроки обязаны иметь видеозапись и хранить ее в течение 48 часов. | Demorgan 100 минут / WARN / Ban 10-15 дней / Hardban 15-30 дней / PermBan + Обнуление","","8.5 Сотрудникам силовых структур запрещено находиться на территории криминальной организации. | Demorgan 90 минут / WARN","Исключение: рейд, работа под прикрытием, военное положение.","","8.6 Снятие функционального розыска с игрока возможно лишь сотрудником, которым он был выдан. | Demorgan 50-100 минут / Warn / Ban / HardBan 5-15 дней","Исключение: решение суда / прокуратуры / одобрение главного следящего за гос. фракциями."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('gov-rules', '9. Судебная власть', NULL, NULL, '["9.1 Лидер судебной ветви может назначаться главным следящим за государственными структурами.","","9.2.1 Председатель верховного суда исполняет обязанности главного судебного органа.","","9.2.2 Председатель верховного суда имеет возможность назначить не более 3 верховных судей.","","9.3 Решение председателя верховного суда можно обжаловать путем IC иска.","","9.4.1 Снятие председателя верховного суда происходит путем написания кейс-файла.","","9.4.2 За неверные решения судья получает 1 штрафной балл.","","9.4.3 При достижении 5 штрафных баллов верховного судью снимают с должности.","","9.5 По решению верховного судьи лидер государственной организации может быть снят.","","9.6 Все судебные процессы происходят в здании правительства.","","9.7.1 Судебному подразделению необходимо начать принятие обращения граждан не позднее 48 часов с момента обращения. | Штрафной балл","","9.7.2 Принятие мер / расследование должно начаться не позднее 48 часов с момента обработки иска. | Штрафной балл","","9.7.3 Ходатайства должны рассматриваться не позднее 48 часов с момента подачи. | Предупреждение / Штрафной балл","","9.7.4 На исполнение судебных актов устанавливается время до 72 часов. | Штрафной балл","","9.7.5 После заседания суд должен дать мотивированное решение в течение 48 часов. | Штрафной балл"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('gov-rules', '10. Weazel News', NULL, NULL, '["10.1 Weazel News - свободное новостное агентство, подчиняющееся правительству и министерству культуры.","","10.2 Сотрудники Weazel News обязаны проверять, редактировать и обрабатывать функциональные объявления граждан. | Беседа / Выговор лидеру","","10.3 Запрещена подача объявлений / новостей в обход функционала проекта. | WARN","","10.4 Запрещена подача объявлений / новостей не содержащих всеобщий характер. | Demorgan 15-35 минут","Пример: приветы, поздравления конкретных игроков/семей и т.п.","","10.5 Подача объявлений / новостей не должна содержать оскорбительный характер или нарушать другие правила проекта."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('gov-rules', '11. Правила проведения РП допроса', NULL, NULL, '["11.1 РП допрос должен иметь веские IC основания. | WARN","","11.2 Допрашиваемому запрещено нарушать правила PG. | Demorgan 15-100 минут / Ban 2-5 дней","","11.3.1 Допрашиваемый не обязан отвечать четко на вопросы связанные с его рангом / влиянием в криминальной организации.","","11.3.2 Сотрудникам гос. фракций запрещено задавать некорректные вопросы в /do. | WARN","","11.4.1 Допрос не должен нести грубый насильственный характер, запрещено наносить телесные повреждения. | WARN","","11.4.2 Допрос без написанной РП ситуации должен происходить исключительно в допросной или интерьере фракции. | WARN","","11.4.3 Допрос с написанной РП ситуацией должен происходить исключительно вне зеленых зон. | WARN","","11.5 Разрешено использование детектора лжи. | WARN при нарушении","Необходима полная отыгровка включения и подключения.","Запрещено задавать прямые вопросы (состоит ли в криминальной организации, какой ранг и т.п.).","","11.6 Допрос не должен длиться более 60 минут. | Demorgan 35-90 минут всем участникам допроса со стороны государственной фракции","","11.7 Запрещено намеренно затягивать RP допрос. | WARN"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('gov-rules', '12. Правила обыска багажников транспортных средств', NULL, NULL, '["12.1.1 Выдача ордера на обыск любого транспортного средства настраивается лидером фракции.","","12.1.2 Ордер может быть выдан на основе: массовых беспорядков, увеличения оборота незаконного оружия, военного положения, решению суда, решению прокурора, рейда и т.п.","","12.1.3 Ордер можно использовать лишь на те транспортные средства, которые фигурируют в кейс-файле / делопроизводстве / судебном иске / нарушении.","","12.2 При обычном патрулировании обыск транспортного средства можно произвести исключительно за нарушение УК.","","12.3 При ограблении бизнеса / банка / дома, при нападении на Форт-Занкудо / Остров Кайо-Перико государственные структуры вправе осмотреть все близстоящие транспортные средства.","","12.4 При использовании ордера обязательно иметь видеоматериал и хранить его 48 часов."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('frb', 'Глава I. Общие положения', NULL, NULL, '["Статья 1. ФРБ — орган внутренней разведки и правоохранительная структура с федеральной юрисдикцией. Составная часть Департамента юстиции.","Статья 2. ФРБ находится в подчинении Генерального прокурора штата Сан-Андреас.","Статья 3. Руководство деятельностью ФРБ осуществляется Директором ФРБ.","","Статья 4. Правовую основу деятельности ФРБ составляют Конституция штата, настоящий Закон, другие законы и нормативные акты.","","Статья 5. Принципы деятельности: законность, уважение прав и свобод, гуманизм, единство системы, конспирация.","","Статья 6. Сотрудники ФРБ обязаны идентифицировать себя по первому требованию гражданина.","Примечание: Госслужащий вправе потребовать предъявления удостоверения сотрудника специализированного отдела (IB и CID)."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('frb', 'Глава II. Основные направления деятельности ФРБ', NULL, NULL, '["Статья 7. Направления деятельности:","- Защита от террористических атак;","- Защита от операций иностранной разведки и шпионажа;","- Защита от кибератак;","- Борьба с государственной коррупцией;","- Защита гражданских прав;","- Борьба с преступностью;","- Контрразведывательная деятельность;","- Борьба с беловоротничковой и насильственной преступностью;","- Обеспечение информационной безопасности."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('frb', 'Глава III. Полномочия ФРБ', NULL, NULL, '["Статья 8. Обязанности ФРБ: информирование Генпрокурора, выявление и предотвращение незаконной деятельности, расследование федеральных преступлений, борьба с терроризмом, контроль оборота наркотиков и оружия, обеспечение безопасности массовых мероприятий, госзащита потерпевших и свидетелей.","","Статья 9. Права ФРБ: установление конфиденциального сотрудничества, проведение ОРМ, использование спецподразделений, проникновение в преступные группы, предварительное следствие, беспрепятственный вход в помещения при угрозе, оцепление местности, проверка документов, досмотр, получение информации от госорганов, вызов граждан на допрос, проведение экспертиз, запрос помощи других структур."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('frb', 'Статья 10. Применение оружия и спецсредств', NULL, NULL, '["ч. 1 Сотрудники имеют право на применение боевой техники, оружия, спецсредств и физической силы.","ч. 3 В состоянии необходимой обороны вправе использовать любые подручные средства.","ч. 4 Сотрудники не несут ответственность за вред при законном применении."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('frb', 'Статья 12. Преступления, расследуемые ФРБ', NULL, NULL, '["ч. 1 Федеральные преступления, связанные с покушением или убийством лица со статусом неприкосновенности.","ч. 2 Федеральные преступления, связанные с антикоррупционным законодательством.","ч. 3 Внутренняя проверка в госструктурах с одобрения Генпрокурора."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('frb', 'Статья 13. Ограничения по ДК', NULL, NULL, '["ФРБ не уполномочено осуществлять контроль за ДК, за исключением:","Ст.1 — обязанность предъявления документов;","Ст.2 — обязанность остановиться по требованию сотрудника.","Применяется исключительно в рамках задач ФРБ, не для общего патрулирования."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('frb', 'Глава IV. Применение мер госпринуждения', NULL, NULL, '["Статья 14. Оцепление участков местности — при ликвидации ЧС, массовых беспорядках, розыске, преследовании, контртеррористической операции.","","Статья 15. Применение огнестрельного оружия: защита от посягательства, пресечение завладения оружием, освобождение заложников, задержание тяжких преступников, пресечение побега, остановка ТС, разрушение запорных устройств.","","Статья 16. Применение спецсредств: отражение нападения, пресечение преступления, задержание, конвоирование, пресечение массовых беспорядков.","","Статья 17. Применение физической силы: пресечение правонарушений, доставление в служебное помещение, преодоление противодействия."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('frb', 'Глава V. Структура ФРБ', NULL, NULL, '["Статья 18. ATF — антитеррористическое спецподразделение. Ответственно за спецоперации, освобождение заложников, силовую поддержку.","Статья 19. CID — криминально-следственное подразделение. Расследование федеральных преступлений, разведка, внедрение под прикрытие.","Статья 20. FNA — отдел по обучению сотрудников, набор стажеров, кадровый учёт.","Статья 21. IB — внутренняя разведка. Расследование должностных преступлений, надзор за госструктурами. Иные сотрудники ФРБ не вправе вмешиваться в деятельность IB.","Статья 22. Free Agents — переговорщики и координаторы действий."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('frb', 'Глава VI. Правовое положение сотрудника', NULL, NULL, '["Статья 23. Гарантии правовой защиты: сотрудник — представитель госвласти под защитой государства. Законные требования обязательны. Не допускаются привод, задержание, обыск без ордера (кроме угрозы жизни или совершения преступления).","Статья 24. Сотрудник несет ответственность за свои действия.","Статья 25. Любой гражданин должен пройти отбор по законопослушности, благонадёжности и профессиональности."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('frb', 'Глава VII. Контроль и надзор', NULL, NULL, '["Статья 26-27. Контроль осуществляет Генеральный прокурор. Генпрокурор имеет право требовать любые отчеты.","Статья 28. Неисполнение служебных обязанностей и разглашение гостайны влечёт ответственность."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('frb-charter', 'Глава I. Основные положения', NULL, NULL, '["Статья 1. Устав — свод норм и правил, регулирующих деятельность и внутриведомственные отношения Федерального расследовательского бюро (ФРБ).","Статья 2. Деятельность сотрудников ФРБ регулируется законодательством штата Сан-Андреас, постановлениями Сената, нормативными актами Губернатора, Вице-Губернатора, Генерального прокурора и его заместителей, данным уставом.","Статья 3. Данный устав является общепринятым и обязательным для исполнения всеми сотрудниками ФРБ.","Статья 4. Изменения и дополнения в настоящий устав вносятся Директором ФРБ и подлежат обязательному утверждению Генеральным прокурором штата Сан-Андреас в установленном законом порядке."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('frb-charter', 'Глава II. Иерархия и структура ФРБ', NULL, NULL, '["Статья 5. Структура ФРБ представляет собой иерархическую систему, основанную на принципах единоначалия и строгого соблюдения субординации. Штатное расписание и структура подразделений утверждаются Директором ФРБ.","Статья 6. Руководство деятельностью ФРБ осуществляют Директор, его заместители и советники, которые определяют основные направления оперативной работы, кадровой политики и стратегического развития ведомства.","Статья 7. Оперативную и административную деятельность в ФРБ обеспечивают специализированные отделы (бюро). Все сотрудники ФРБ, за исключением руководящего состава, обязаны состоять в одном из оперативных отделов.","ч. 1 В состав ФРБ входят следующие отделы:","а) Intelligence Branch [IB] — отдел внутренней разведки;","б) Federal National Academy [FNA] — отдел по обучению сотрудников;","в) Criminal Investigative Division [CID] — отдел криминальных расследований;","г) Drug Enforcement Administration [DEA] — управление по борьбе с наркотиками;","д) Hostage Rescue Team [HRT] — группа освобождения заложников;","е) Air Force [AF] — отдел воздушной поддержки;","ж) National Security Branch [NSB] — отдел национальной безопасности;","з) Free Agent [FA] — свободные агенты;","и) Anti Terror Force [ATF] — отдел по борьбе с терроризмом;","к) Counter Terrorism Division [CTD] — дивизион по противодействию терроризму;","л) Trainee Bureau [TB] — подразделение первичного отбора и обучения.","","Статья 8. Система должностных званий (рангов) ФРБ:","Младший состав: 1. Trainee, 2. Jr. Agent","Основной состав: 3. Agent, 4. Senior Agent, 5. Special Agent, 6. Supervisor Special Agent, 7. Analytics Agent, 8. Recruiting Agent, 9. Free Agent","Старший состав: 10. Deputy Head of Bureau, 11. Head of Bureau, 12. Curator of Bureau","Руководящий состав: 13. Advisor Director, 14. Deputy of Director, 15. Director","","Статья 9. Сотруднику ФРБ запрещено обращаться не по иерархии.","Статья 10. Сотрудник ФРБ обязан подчиняться приказам старшего состава своего отдела, старшему составу IB и руководящему составу ФРБ.","Статья 11. Директор ФРБ, его заместители и советники действуют от имени учреждения, представляют его интересы в органах и собраниях государственной власти и местного самоуправления, коммерческих и некоммерческих организаций."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('frb-charter', 'Глава III. Запреты для сотрудников ФРБ', NULL, NULL, '["Статья 12. Общие запреты:","а) Нарушать законодательную базу штата Сан-Андреас.","б) Принимать участие в нелегальной или криминальной деятельности.","в) Халатно относиться к своим должностным обязанностям и полномочиям.","г) Злоупотреблять должностными полномочиями в личных, корыстных или иных целях.","д) Использовать табельное оружие и служебные специальные средства не по прямому назначению.","е) Принимать, требовать или вымогать взятки в любом виде.","","Статья 13. Запреты, связанные с субординацией и коммуникацией:","а) Игнорировать входящие вызовы по рации от старшего и руководящего состава.","б) Нарушать субординацию в коллективе и по отношению к старшему составу.","в) Создавать, участвовать или провоцировать конфликты в коллективе.","г) Допускать клевету, обман, намеренное введение в заблуждение коллег или руководства.","д) Ругаться матом, оскорблять, хамить, унижать или неуважительно относиться к жителям штата и коллегам.","","Статья 14. Трудовые и дисциплинарные нарушения:","а) Нарушать утвержденный график работы.","б) Прогуливать рабочий день.","в) Отсутствовать на рабочем месте более трех дней без одобренного заявления на отпуск.","г) Выпрашивать, намекать или иным образом добиваться получения новой должности вне установленного порядка аттестации.","д) Злостно нарушать строевой порядок во время построений и официальных мероприятий.","е) Игнорировать обязательные построения и брифинги.","","Статья 15. Запреты, связанные с состоянием и внешним видом:","а) Находиться в состоянии алкогольного или наркотического опьянения при исполнении.","б) Не соответствовать установленному дресс-коду.","в) Находиться на закрытой территории ФРБ в личной (гражданской) одежде.","Примечание: Разрешено следование в личной одежде от входа до раздевалки, а также до склада с целью сдачи вооружения. Исключение: сотрудники отдела CID, старший и руководящий состав.","","Статья 16. Запреты на использование имущества и транспорта:","а) Использовать служебный транспорт в личных целях.","б) Использовать транспорт Бюро, находясь не при исполнении.","в) Возвращать служебный транспорт на парковку, если в нем менее 35 литров топлива.","г) Передвигаться на личном транспорте по внутренней закрытой территории ФРБ.","","Статья 17. Запреты на действия в нерабочее время:","а) Во время перерыва или отпуска пользоваться служебным положением, применять табельное оружие.","Примечание: Перед уходом на перерыв сотрудник обязан сдать табельное оружие на склад.","","Статья 18. Ограничения по отдельным видам деятельности:","а) Играть в азартные игры, посещать казино, участвовать в GunGame, находясь в рабочей форме.","б) Младшему составу проводить процессуальные действия до завершения стажировки.","в) Создавать помехи или вмешиваться в оперативную работу других отделов.","","Статья 19. Запреты, связанные с имуществом и документацией:","а) Помещать на склад организации предметы, не относящиеся к служебной деятельности.","б) Самовольно получать доступ к документации других отделов.","в) Менять паспортные данные без предварительного уведомления руководства.","","Статья 20. Репутационные и процессуальные запреты:","а) Совершать действия, подрывающие репутацию ФРБ.","б) Нарушать установленные правила агитации.","в) Сотрудникам младшего состава иметь хотя бы один строгий выговор.","","Статья 21. Обязанности руководящего состава:","а) Сотрудник, выдавший взыскание, обязан в течение шести часов рассмотреть заявление на обжалование.","б) Старшему составу запрещено переводить сотрудников не в свой отдел.","в) Запрещено повышать сотрудников без одобренного отчета.","","Статья 22. Документационная дисциплина:","а) Сотрудник обязан в срок не более двух часов заполнять всю обязательную отчетность."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('frb-charter', 'Глава IV. Права сотрудника ФРБ', NULL, NULL, '["Статья 23. Сотрудники ФРБ обладают следующими правами:","ч. 1 Право на увольнение по собственному желанию.","ч. 2 Право на доступ к содержимому склада организации после успешной стажировки.","ч. 3 Право на получение денежного поощрения (премии) по итогам еженедельного отчета.","ч. 4 Право на перерыв в течение рабочего дня и на отпуск."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('frb-charter', 'Глава V. Рабочий день, перерыв и отпуск', NULL, NULL, '["Статья 24. Рабочее время отделов:","IB, FNA — с 14:00 до 22:00;","CID, DEA, AF, FA — с 14:00 до 02:00;","HRT, ATF, CTD — с 12:00 до 02:00;","NSB, TB — с 14:00 до 00:00.","","Статья 25. Сотрудник имеет право на оплачиваемый перерыв до 120 минут, уведомив начальство.","Статья 26. Начальство отдела имеет право вызвать подчиненного с перерыва.","Статья 27. Сотрудники от 3 ранга имеют право взять неоплачиваемый отпуск от 3 до 7 дней."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('frb-charter', 'Глава VI. Внешний вид сотрудников FIB', NULL, NULL, '["Статья 28. На службе у сотрудника всегда должны быть жетон, бейдж или нашивка, удостоверение и боди-камера.","Статья 29. На рабочем месте каждый сотрудник младшего и среднего состава обязан носить форму своего отдела."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('frb-charter', 'Глава VII. Регламент нахождения в строю', NULL, NULL, '["Статья 30. Общий строй имеет право собрать старший состав HRT, AF, IB и руководящий состав.","Статья 31. Кураторы и начальники отделов имеют право собрать строй своего отдела.","Статья 32. Запрещено препятствовать проведению строя другого отдела.","Статья 33. В строю запрещается: разговаривать без разрешения, жестикулировать, использовать телефон, держать оружие, выходить без приказа, стрелять, перебивать, задавать вопросы, спать, есть, курить, принимать неестественную позу, танцевать.","Статья 34. Старший по званию обязан вносить отметки присутствующих.","Статья 35. По прибытию в строй сотрудник обязан встать по стойке смирно.","Статья 36. Начальники отделов ответственны за укомплектование личного снаряжения.","Статья 37. Сотрудник может быть вызван на работу в нерабочее время.","Статья 38. При наличии уважительной причины для неявки необходимо подать обжалование."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('frb-charter', 'Глава VIII. Система дисциплинарных взысканий', NULL, NULL, '["Статья 39. FNA имеют право выдавать взыскания стажерам.","Статья 40. IB имеют право выдавать взыскания младшему и среднему составу.","Статья 41. Старший состав IB имеет право выдавать взыскания старшему составу других отделов.","Статья 42. Старший состав имеет право выдавать взыскания своим сотрудникам.","Статья 43. Руководящий состав имеет право выдавать взыскание любому сотруднику.","Статья 44. Любое лицо, имеющее право на дисциплинарное производство, может применять санкции за неявку в строй.","Статья 45. Снять активное взыскание может сотрудник, выдавший его, старший состав IB или руководство.","","Статья 46. Виды дисциплинарных взысканий:","а) Предупреждение;","б) Устный выговор;","в) Строгий выговор;","г) Понижение в должности;","д) Увольнение.","","Статья 47. Сотрудник, выдающий взыскание, обязан указать основание — конкретный пункт устава.","Статья 48. Обжалование взысканий у лица, выдавшего его, у старшего состава IB или руководства.","Статья 49. IB и руководство уполномочены на контроль за соблюдением устава и проведение внутренних проверок."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('ord', 'Глава 1. Общие положения', NULL, NULL, '["Статья 1. Оперативно-розыскная деятельность — вид деятельности, осуществляемой гласно и негласно оперативными подразделениями государственных органов в целях защиты жизни, здоровья, прав и свобод человека и гражданина, собственности, обеспечения безопасности общества и государства.","","Статья 2. Задачи ОРД:","а) выявление, предупреждение, пресечение и раскрытие правонарушений;","б) осуществление розыска лиц, скрывающихся от правоохранительных органов;","в) добывание информации о событиях, создающих угрозу безопасности штата;","г) установление имущества, подлежащего конфискации;","д) идентификация личности граждан посредством изучения ID-card.","","Статья 3. Принципы ОРД: законность, уважение прав и свобод, конспирация, сочетание гласных и негласных методов.","","Статья 4. Правовую основу ОРД составляют Конституция штата, настоящий Закон, другие законы и нормативные акты.","","Статья 5. Соблюдение прав и свобод человека и гражданина:","ч. 1 Должностные лица должны обеспечивать соблюдение прав на неприкосновенность частной жизни.","ч. 2 Не допускается ОРД для достижения целей, не предусмотренных Законом.","ч. 3 Лицо вправе обжаловать действия органов в вышестоящий орган, прокурору или в суд.","ч. 4 Запрещается:","- проводить ОРМ в интересах политических партий;","- принимать негласное участие в работе органов власти;","- разглашать сведения о частной жизни;","- фальсифицировать результаты ОРД;","- выдавать боло-розыск с причиной ''ОРМ'' без ордера.","Исключение: Ордер/Решение суда или прокуратуры, решение Генпрокурора.","При выдаче розыска обязательно указание четкой диспозиции статьи и кодекса.","Пример корректной причины: ''Нарушение 15.6 ч.1 УК СА''","Розыск может быть выдан лишь в пределах 3-4 часов с момента ситуации."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('ord', 'Глава 2. Проведение ОРМ', NULL, NULL, '["Статья 6. Оперативно-розыскные мероприятия:","а) Опрос;","б) Наведение справок;","в) Сбор образцов для сравнительного исследования;","г) Контрольная закупка;","д) Исследование предметов и документов;","е) Наблюдение;","ё) Отождествление личности;","ж) Обследование помещений, зданий, сооружений, участков местности и ТС;","з) Контроль почтовых отправлений, телеграфных и иных сообщений;","и) Прослушивание телефонных переговоров;","й) Снятие информации с технических каналов связи;","к) Оперативное внедрение;","л) Контролируемая поставка;","м) Оперативный эксперимент;","н) Получение компьютерной информации.","","Статья 7. Основания для проведения ОРМ:","а) Наличие возбужденного дела;","б) Сведения о: признаках правонарушения, угрозе безопасности, лицах в розыске, без вести пропавших;","в) Поручения прокурора или определение суда;","г) Запросы других органов ОРД.","","Статья 8. Условия проведения ОРМ:","ч. 1 Гражданство, пол, место жительства и др. не являются препятствием.","ч. 2 ОРМ, ограничивающие права на тайну переписки и неприкосновенность жилища, допускаются на основании судебного решения.","ч. 3 Прослушивание переговоров допускается только в отношении подозреваемых.","","Статья 9. Использование результатов ОРД:","Результаты могут быть использованы для подготовки следственных действий, для розыска лиц, для принятия решений, а также служить поводом для возбуждения дела."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('ord', 'Глава 3. Органы, осуществляющие ОРД', NULL, NULL, '["Статья 10. Право осуществлять ОРД предоставляется оперативным подразделениям:","а) Правоохранительных органов;","б) Органов следствия (прокуратура).","","Статья 11. Обязанности органов ОРД:","а) Принимать меры по защите прав и свобод;","б) Исполнять поручения прокурора и решения суда;","в) Соблюдать правила конспирации.","","Статья 11.1. Обязанности, связанные с проведением определенных ОРМ:","ч. 1 После оперативного эксперимента в течение часа уведомить Генерального прокурора.","ч. 2 Оперативное внедрение возможно только при заблаговременном уведомлении Генерального прокурора."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('ord', 'Глава 4. Содействие граждан', NULL, NULL, '["Статья 12. Отдельные лица могут с их согласия привлекаться к ОРМ с сохранением конфиденциальности. Эти лица обязаны сохранять тайну."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('ord', 'Глава 5. Контроль и надзор', NULL, NULL, '["Статья 13. Контроль за ОРД осуществляют Генеральный прокурор и его заместители.","","Статья 14. Прокурорский надзор:","ч. 1 Прокурорский надзор осуществляют Генеральный прокурор и уполномоченные им прокуроры.","ч. 2 По требованию прокурора руководители органов ОРД представляют оперативно-служебные документы.","ч. 3 Сведения о негласных сотрудниках представляются только с их письменного согласия.","","Статья 15. Руководители органов ОРД несут персональную ответственность за соблюдение законности."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('closed-areas', 'Статья 1. Охраняемые объекты', NULL, NULL, '["Охраняемыми объектами являются:","- Капитолий штата Сан-Андреас, кроме территории холла","- Участки LSPD и LSCSD и служебные парковки, кроме территории холла","- Территория острова Кайо-Перико, воды на 1 милю от берега","- Здания медицинских учреждений, здание Weazel News","- Авианосец, воды на 1 милю от авианосца","- Здание Суда","","Законные цели визита:","LSPD/LSCSD — оформление лицензии CDWL, трудоустройство, заявление о правонарушении, явка с повинной.","FIB — добровольная сдача нелегальных предметов, трудоустройство.","Government — взаимодействие с секретарем, снятие судимости, оформление лицензий, голосование.","EMS — получение медицинской помощи, оформление документации.","WN — получение услуг СМИ, трудоустройство.","","Примечание: Сотрудники госструктуры могут потребовать покинуть территорию, если цель визита не соответствует правилам."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('closed-areas', 'Статья 2. Особо охраняемые объекты', NULL, NULL, '["Особо охраняемыми объектами являются:","- Форт Занкудо","- Офис FIB"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('closed-areas', 'Статья 3. Доступ на особо охраняемые объекты', NULL, NULL, '["Форт Занкудо. Имеют доступ: военнослужащие National Guard; Губернатор; Вице-Губернатор; Глава Департамента Администрации Губернатора; Генеральный прокурор и его заместители; Глава DNS; сотрудники ОГП; другие граждане в сопровождении генералитета NG или при пропуске; EMS во время проверок.","","Авианосец. Имеют доступ: военнослужащие NG; Губернатор; Вице-Губернатор; сотрудники правительства в сопровождении; Глава DNS; сотрудники госструктур при поставке материалов; другие граждане в сопровождении генералитета; временный доступ по распоряжению Генпрокурора.","","Офис FIB. Имеют доступ: сотрудники FIB; Губернатор; Вице-Губернатор; Генеральный прокурор и его заместители; адвокаты только на территории КПЗ; Глава DNS; EMS; сотрудники ОГП; Директора FIB; руководство госорганов в случае задержания подчиненных.","","Примечание: частные адвокаты могут проходить на территорию КПЗ только в рамках вызова через телефон. После окончания вызова адвокат обязан в течение 5 минут покинуть территорию.","","Капитолий и здание суда. Имеют доступ: сотрудники Правительства; EMS; участники судебного процесса — на время заседания; сенаторы; иные лица в сопровождении сотрудников Правительства или при пропуске.","","Участки LSPD/LSCSD. Имеют доступ: Губернатор; Вице-Губернатор; Генеральный прокурор; Глава DNS; сотрудники ОГП; адвокаты только на КПЗ; сотрудники IB на КПЗ; EMS; руководство госорганов при задержании подчиненных; другие граждане при пропуске.","","Здания медицинских учреждений. Имеют доступ: Губернатор; Вице-Губернатор; сотрудники Администрации Губернатора; Главы департаментов; сотрудники ОГП; сотрудники правоохранительных структур; EMS.","","Остров Кайо-Перико. Имеют доступ: Губернатор; Вице-Губернатор; Главы департаментов; сотрудники ОГП; сотрудники госструктур при исполнении.","","Weazel News. Имеют доступ: Губернатор; Вице-Губернатор; сотрудники Администрации Губернатора; Главы департаментов; сотрудники ОГП; сотрудники правоохранительных структур; EMS. Посетители допускаются на территорию холла."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('closed-areas', 'Статья 4. Регламент посещения здания суда', NULL, NULL, '["1.1. Допуск посетителей осуществляется по предъявлению документов, удостоверяющих личность.","","1.2. Основания для отказа:","- отсутствие или отказ предъявить документы;","- отказ от личного досмотра;","- обнаружение запрещенных предметов;","- внешний вид, не отвечающий требованиям (спортивная/пляжная одежда, шорты выше колен);","- состояние опьянения;","- прибытие с животными.","","1.2.1. Судебный пристав, судья вправе потребовать предоставить документ.","1.2.2. Пристав вправе потребовать покинуть здание при нарушении порядка.","1.2.3. Судья вправе ограничить доступ для посетителей при закрытом заседании.","1.2.4. Свидетели допускаются по приглашению судьи."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('closed-areas', 'Статья 5. Визуализация территорий', NULL, NULL, '["- Белым цветом — прилегающие территории к гос. объектам.","- Желтым и черным — охраняемые объекты.","- Красным — особо охраняемые объекты.","","На прилегающих территориях обеспечивается беспрепятственный доступ всем гражданам.","Примечание: при нарушении законодательства по требованию сотрудника лицо обязано покинуть территорию."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('closed-areas', 'Статья 6. Полномочия сотрудников', NULL, NULL, '["Сотрудники правоохранительных органов, военнослужащие вправе требовать от граждан назвать причину пребывания на охраняемых и особо охраняемых объектах, а также на прилегающих территориях, проверять документы."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('theory', '🎯 Объект преступления', NULL, NULL, '["Общественные отношения, охраняемые уголовным законом, которым причиняется вред","Пример для ст.13.2: Общественные отношения в сфере здоровья населения и общественной нравственности","Пример для ст.12.8: Общественные отношения в сфере общественной безопасности","Пример для ст.17.6: Общественные отношения в сфере порядка управления"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('theory', '👤 Субъект преступления', NULL, NULL, '["Лицо, совершившее преступление, которое может нести уголовную ответственность","Признаки: вменяемое физическое лицо, достигшее возраста уголовной ответственности (16 лет, по некоторым — 14)","Специальный субъект: для ст.15.1, 15.4, 15.6 — должностное лицо / госслужащий"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('theory', '⚙️ Объективная сторона', NULL, NULL, '["Внешнее проявление преступления — действие или бездействие, последствия, причинная связь","Пример для ст.13.2: Незаконное хранение наркотического средства массой от 3 граммов","Пример для ст.17.6: Открытый отказ выполнить законное требование сотрудника","Пример для ст.17.3: Унижение чести представителя власти в неприличной форме"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('theory', '🧠 Субъективная сторона (вина)', NULL, NULL, '["Психическое отношение лица к своему деянию","Прямой умысел (ст.2.3 ч.2): осознавал опасность, предвидел последствия, желал их наступления","Косвенный умысел (ст.2.3 ч.3): осознавал, предвидел, не желал, но сознательно допускал","Неосторожность (ст.2.4): легкомыслие (самонадеянно рассчитывал предотвратить) или небрежность (не предвидел, но должен был)"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('theory', '📋 Диспозиция', NULL, NULL, '["Краткое описание конкретного деяния, которое вменяется подозреваемому","Пример: «Хранение при себе наркотического вещества массой 15 граммов»","Пример: «Отказ выполнить законное требование сотрудника выйти из автомобиля»"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('theory', '👥 Соучастие (ст.3.3-3.6 УК)', NULL, NULL, '["Исполнитель — непосредственно совершил преступление","Организатор — организовал совершение преступления или руководил его исполнением","Подстрекатель — склонил другое лицо к совершению преступления","Пособник — содействовал советами, средствами, либо заранее обещал скрыть преступника или следы"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('theory', '📊 Стадии совершения преступления (ст.3.1)', NULL, NULL, '["Приготовление — приискание орудий, сговор. Наказание — до 1/2 максимального срока","Покушение — действия, непосредственно направленные на преступление, но не доведённые до конца. Наказание — до 3/4 максимального срока","Оконченное преступление — в деянии содержатся все признаки состава преступления"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('theory', '⚖️ Смягчающие обстоятельства (ст.5.3 УК)', NULL, NULL, '["Явка с повинной, активное способствование раскрытию","Добровольное возмещение ущерба","Совершение впервые вследствие стечения обстоятельств","Противоправность поведения потерпевшего"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('theory', '⚠️ Отягчающие обстоятельства (ст.5.4 УК)', NULL, NULL, '["Совершение в составе группы лиц","Из мести за правомерные действия","С особой жестокостью","С использованием доверия в силу служебного положения","В состоянии опьянения","Рецидив"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('theory', '💰 Штраф = Нет судимости!', NULL, NULL, '["По ст.5.8 ч.3 УК: При назначении наказания в виде уголовного штрафа судимость НЕ ВОЗНИКАЕТ даже при 5 звёздах","Человек может получить 5 звёзд, заплатить штраф (если статья позволяет) и НЕ получить судимость — может работать в гос.структурах"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('theory', '🔍 Состав преступления (матрица)', NULL, NULL, '["СОВОКУПНОСТЬ четырёх элементов:","1) Объект — общественные отношения","2) Объективная сторона — деяние, последствия, причинная связь","3) Субъект — лицо, возраст, вменяемость","4) Субъективная сторона — вина, мотив, цель","ОТСУТСТВИЕ хотя бы одного элемента = НЕТ состава преступления (ст.1.8 примечание)"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('rules', '1. Общее положение', NULL, NULL, '["1.1 На проекте действует прецедентная система правил. (Если игрок совершил правонарушение, которое не описано ни в каких правилах проекта, то он может быть наказан с разрешения ГА.)","1.2 Проект позиционирует себя как русскоязычный, все диалоги должны происходить на русском языке. | Mute 60-240 минут. Исключение: отдельные слова и фразы для отыгровки роли.","1.3 Администрация не компенсирует средства, услуги, предметы и т.д., которые были утрачены в силу функционального воздействия / задумки системы.","1.4 Виды наказаний: PermBan, HardBan, Ban, Demorgan, GunBan, Mute, Warn."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('rules', '2. Положение об аккаунте и персонаже', NULL, NULL, '["2.1 Максимум 1 аккаунт на человека. | PermBan","2.2 Запрещено передавать аккаунт 3-м лицам. | PermBan","2.4 Запрещена продажа / обмен игровых аккаунтов. | PermBan","2.5 Запрещено одновременно состоять несколькими персонажами во фракции / семье. | WARN","2.6 Ограничения по участию в мероприятиях накладываются на персонажа, вне зависимости от его фракции/семьи.","2.7 Запрещено владеть имуществом без игровой активности (мин. 4 часа в неделю, 30 в месяц). | Изъятие имущества","2.8 Запрещено иметь более 1 бизнеса на аккаунте. | Изъятие","2.9 Запрещены nonRP никнеймы. | Demorgan до смены","2.10 Запрещено играть за персонажа противоположного пола. | Demorgan до смены внешности"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('rules', '3. Модерация платформ', NULL, NULL, '["3.1 Администрация вправе вынести наказания по зафиксированному нарушению с модерируемых платформ.","3.2 Под модерацией: игровые сервера, Discord, Twitch/Youtube, видео/скриншоты, форум, внутриигровые системы.","3.4 Сообщения между игроками не входят в зону модерации, кроме грубых нарушений.","3.6 Запрещено использовать запрещённые стримерской платформой слова. | Mute 60-120 мин / Ban 3-10 дней","3.7.1 Запрещён намеренный ''стрим-снайп''. | Ban 7-30 дней","3.7.2 Запрещено оказывать помощь стримерам без просьбы. | Kick / Demorgan 15 мин"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('rules', '4. Игровые чаты', NULL, NULL, '["4.1 Текстовый и голосовой чат — IC, запрещено OOC общение. | Mute 30-90 мин / Demorgan 5 мин","4.2 Запрещено завуалированное оскорбление или упоминание родственников. | Ban 5-30 дней","4.3 Прямое оскорбление родственников. | HardBan 30-60 дней","4.4 Спам, флуд. | Mute 10-60 мин","4.5 Программы для изменения тональности голоса. | Mute 10-60 мин","4.6 Громкие или мешающие звуки. | Mute 10-120 мин","4.7 OOC травля и оскорбления игроков. | Demorgan 15-60 мин / Ban 3-10 дней","4.8-4.12 Правила глобальных чатов: запрещены оскорбления, MG, бессмысленные сообщения, CapsLock, спам рацией"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('rules', '5. Role Play процесс', NULL, NULL, '["5.1 DM (Deathmatch) — убийство без IC причины. | GunBan 6 ч / Demorgan 120 мин / Ban 3-30 дней","5.2 DB (DriveBy) — намеренный наезд. | Demorgan 30-90 мин / Ban 3-30 дней","5.3 NonRP — поведение вопреки РП логике (езда по горам/воде, езда по встречной более 15 сек). | Demorgan 15-90 мин","5.4 NLR — после смерти забыть последние 15 минут. | Demorgan 90 мин","5.5 PG — преувеличение возможностей (правило 1x1, для силовиков 1x2 при бронежилете). | Demorgan 35-90 мин","5.6 SK — стрельба на месте появления. | GunBan 8 ч / Ban 2-5 дней","5.7 TK — урон по своим. | GunBan 2-6 ч / Demorgan 50-120 мин","5.8 MG — использование OOC информации. | Demorgan 20-90 мин","5.9 Уход от RP (АФК, выход, игнорирование /do). | WARN / HardBan 4-8 дней","5.10 Криминальные действия против EMS в рабочее время. | Demorgan 90 мин","5.11 Поднимать предметы во время перестрелки. | Demorgan 35 мин","5.12 Намеренно менять оружие для сохранения. | Изъятие + Demorgan 100 мин","5.13 Вызов госструктур с целью провокации. | Demorgan 15-60 мин","5.15 Запрещены обманы на имущество и лотереи без одобрения. | HardBan 30 дней / PermBan","5.16 Увольнения/повышения с некорректной причиной. | Demorgan 60 мин","5.18 Некорректные отыгровки в /me, /do, /try. | Demorgan 10-35 мин","5.19 Отыгровки в свою пользу. | Demorgan 15-35 мин","5.20 Разрешено игнорировать /do, не несущие смысловой нагрузки или идущие вразрез функционалу."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('rules', '6. Запрещено', NULL, NULL, '["6.1 Помеха работе администрации. | Kick / Mute / Demorgan / Ban","6.2 Скрывать баги и уязвимости. | Ban 7-30 дней / PermBan","6.4 Оскорбление администрации. | Ban 5-30 дней / HardBan 10-60 дней","6.5 Выдавать себя за администратора. | Ban 7-30 дней","6.6 Удалять доказательства нарушения (хранить 48 часов). | Ban 2 дня","6.7 Нанесение вреда экономике сервера. | Ban 30 дней / PermBan","6.8 Использовать баги и уязвимости. | Demorgan 35 мин / Ban 3-30 дней","6.9 Переносить конфликты из OOC в IC и наоборот. | Ban 5-30 дней","6.10 Угрозы в реальной жизни. | Ban 10-30 дней / HardBan 15-30 дней / PermBan","6.11 Обход Anti-AFK. | Ban 5-30 дней","6.12 Возбуждение ненависти по гендерной/социальной принадлежности. | Demorgan 90 мин / Ban 3-15 дней","6.13 Оскорбление вероисповедания, расы, национальности. | Ban 15-30 дней / HardBan 15-30 дней","6.15 Многочисленные нарушения правил. | Ban 15-30 дней / HardBan 15-30 дней / PermBan","6.16 Использование стороннего ПО для преимущества. | PermBan","6.19 Реклама посторонних ресурсов. | HardBan 15-30 дней / PermBan","6.21 Продажа игрового имущества за реальные деньги. | PermBan","6.24 Распространение личной информации. | HardBan 30 дней / PermBan","6.26 Вводить в заблуждение администрацию. | Ban 10-30 дней","6.29 Помеха РП процессу. | Ban 2-5 дней","6.33 Активная реклама промокодов на спавне. | Удаление + Ban 5-30 дней"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('robbery', '1. Общее положение', NULL, NULL, '["📌 1.1. При похищении/ограблении следуют опираться на правила игровых зон.","","📌 1.2. Все похищения/ограбления от криминальных организаций/семей могут совершаться на фракционном/личном транспорте, окрашенном в цвет фракции/семьи. | Demorgan 35 минут","Примечание: разбойное нападение приравнивается к ограблению, на него распространяются все правила ограбления.","Примечание: цвет фракции определяется по цвету фракционного транспорта, цвет семьи — ''Основным цветом''.","Исключение: пешее ограбление.","","📌 1.3. Запрещено держать жертву в интерьерах с целью наживы. | WARN / Ban 3 дня","Исключение: неактивные интерьеры, которые не используются.","Запрещённые интерьеры: швейная фабрика, старые офисы FIB/Weazel News, центр переработки металлолома, Pillbox Hill, шахта Грейт-Чапарал.","","📌 1.4. Запрещено похищать/грабить более 6 человек за раз. | Demorgan 35-90 минут","Примечание: при похищении более 1 человека максимальный интервал между похищениями — 5 минут.","","📌 1.5. Грабителей/похитителей должно быть вдвое больше, чем жертв. | Demorgan 35-90 минут","Исключение: требование покинуть локацию, исключение р.2 п.3, и р.2 п.4.1.","","📌 1.6. Запрещено грабить/похищать, не имея огнестрельного/холодного оружия. | Demorgan 15-35 минут","","📌 1.7. Ограбления/похищения разрешены только членам криминальных организаций/семей. | Demorgan 15-60 минут","","📌 1.8. Причиной для убийства может быть: оскорбление, побег, опознание личности преступника, попытка напугать расправой, нарушение правил PG.","Примечание: запрещено снять маску, тем самым рассекретить свою личность, а после убить. | Demorgan 120 минут","","📌 1.9. Запрещено вызывать сотрудников спец. служб (такси/EMS/силовые структуры и т.д.), подавать объявления в Weazel News для последующих криминальных действий в их сторону. | Demorgan 100 минут / WARN / Ban 2-5 дней","","📌 1.10. Запрещено требовать от жертвы использование гос. волны. | WARN / Ban 2 дня","Примечание: /wnews (зелёнка) также приравнивается к гос. волне.","Исключение: р.3 п.2.4.","","📌 1.11. Жертве ограбления/похищения запрещено использовать OOC средства коммуникации для вызова подкрепления, информирования другой стороны. | WARN","","📌 1.12.1. Запрещено как-либо пытаться унизить жертву в грубом/эротическом характере. | WARN / Ban 2-5 дней","Пример: заставить петь, кричать, заставить сказать аморальные вещи, требовать использование неуместных анимаций.","","📌 1.12.2. Запрещено брить жертву без веской IC причины. | Demorgan 60-100 минут / WARN / Ban 2-5 дней","Пример: стрельба, враждебная дипломатия, оскорбления от жертвы и т.п.","","📌 1.13.1. При похищении/ограблении с жертвой разрешено проводить лишь функциональное взаимодействие. | Demorgan 60-100 минут","Пример: бритьё, ограбление, срез бронежилета, парные анимации.","Примечание: бронежилет разрешено срезать только если он надет на жертве.","Исключение: требование передать содержимое тайника на месте его нахождения; похищения с целью получения информации.","","📌 1.13.2. В случае невыполнения кратких требований игроком, криминальные структуры вправе убить игрока в соответствии с п.5.1 основных правил проекта.","Пример: требование молчать, стоять, не двигаться, поднять руки и т.п.","","📌 1.14. Запрещено совместно похищать/грабить при нейтральной и(или) враждебной дипломатии. | Demorgan 35 минут всем участникам / Выговор лидеру","","📌 1.15.1. Запрещено ограбление рабочих в период с 08:00 до 12:00. | Demorgan 35 минут","Пример: инкассатор, почтальон, дальнобойщик, мусорщик, водитель автобуса, пожарный, электрик.","","📌 1.15.2. Запрещено похищение рабочих. | Demorgan 60-100 минут"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('robbery', '2. Ограбления', NULL, NULL, '["📌 2.1. Ограбления разрешено совершать исключительно через функционал сервера. | Demorgan 35-100 минут / WARN","Пояснение: при грабеже группой лиц (2+ человека) нельзя повторно грабить одного человека.","","📌 2.2. Запрещено требовать передачу недвижимости/транспорта/денег со счёта в банке/одежды/предметов. | Ban 3 дня","","📌 2.3. Минимальное количество грабителей при ограблении — 2 человека. | Demorgan 15-35 минут","Исключение: в период с 17:00 до 10:00 на территории красных зон разрешено грабить в одиночку.","","📌 2.4.1. Минимальное количество грабителей для остановки жертвы в движении на ТС — 4 человека и 2 машины/мотоцикла. | Demorgan 15-35 минут","Исключение: при ограблении полного инкассаторского автомобиля — 6 грабителей;","в ночное время (с 22:00 до 08:00) на территории красных зон — 2 человека на 1 транспорте;","жертва движется на велосипеде.","","📌 2.4.2. Ограбление легкового авто на мототехнике — минимум 2 мотоцикла. | Demorgan 10-35 минут","Исключение: ограбление инкассаторского автомобиля или фуры — минимум 4 мотоцикла. | Demorgan 10-35 минут","","📌 2.5. Запрещено оставлять жертву в стяжках/мешке/верёвке/скотче. | Demorgan 60 минут всем участникам","Исключение: тяжелораненый игрок при дальнейшем взаимодействии, ограбление во время похищения, похищение (если получен выкуп и заложники переданы)."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('robbery', '3. Похищения — минимальное количество похитителей', NULL, NULL, '["📌 3.1. Минимальное количество похитителей — 4. | WARN"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('robbery', '💵 ТАБЛИЦА ВЫКУПОВ (СТ.3.2)', NULL, NULL, '["══════════════════════════════════════════════════════════════════════════════","","📌 3.2.1. Разрешено требовать выкуп за лидера/заместителя фракции/семьи:","Деньги + что-либо из перечня (п.3.2.4).","","══════════════════════════════════════════════════════════════════════════════","","📌 3.2.2. Максимальный выкуп за обычного игрока / игрока враждебной фракции:","💰 35.000$","","📌 3.2.3. Максимальный выкуп за лидера / заместителя фракции:","💰 150.000$","","══════════════════════════════════════════════════════════════════════════════","","📌 3.2.4. Максимальный выкуп оружием / спецсредствами за лидера/заместителя:","","┌─────────────────────────────────────────────────────────────────────────────┐","│ 👮 LSPD / LSCSD                                                            │","│ • 3 MarksmanRifle Mk2                                                     │","│ • 75 (лидер) / 50 (зам) тяжёлых бронежилетов                               │","├─────────────────────────────────────────────────────────────────────────────┤","│ 🪖 SANG (Национальная гвардия)                                             │","│ • 5 CombatMG Mk2 / 3 CombatMG Mk2                                         │","│ • 8000 (лидер) / 4000 (зам) материалов                                    │","├─────────────────────────────────────────────────────────────────────────────┤","│ 🏛️ City Hall (Правительство)                                              │","│ • 1.000.000$ (лидер) / 500.000$ (зам) / 250.000$ (министр)                │","│ • 50 (лидер) / 30 (зам) / 20 (министр) тяжёлых бронежилетов               │","├─────────────────────────────────────────────────────────────────────────────┤","│ 🕵️ FIB                                                                     │","│ • 1 HeavySniper Mk2 / 2 HeavySniper                                       │","│ • 75 (лидер) / 45 (зам) тяжёлых бронежилетов                              │","├─────────────────────────────────────────────────────────────────────────────┤","│ 🚑 EMS                                                                     │","│ • 350 (лидер) / 250 (зам) эпинефрина                                      │","│ • 8 (лидер) / 6 (зам) дефибрилляторов                                     │","├─────────────────────────────────────────────────────────────────────────────┤","│ 💣 Банда                                                                   │","│ • Территория + 10% от любого ресурса на складе (на выбор)                 │","├─────────────────────────────────────────────────────────────────────────────┤","│ 🏠 Семья                                                                   │","│ • 250.000$ (лидер) / 150.000$ (зам)                                       │","├─────────────────────────────────────────────────────────────────────────────┤","│ 📺 Weazel News                                                             │","│ • использование новостной волны / SMS                                     │","│ • 7500 (лидер) / 4000 (зам) технических материалов                        │","└─────────────────────────────────────────────────────────────────────────────┘","","⚠️ Примечание: прочность предметов выкупа должна быть максимальной.","","══════════════════════════════════════════════════════════════════════════════","","📌 3.2.5. При похищении и лидера, и заместителя вместе — потребовать можно лишь ОДНУ часть выкупа. | Demorgan 60 минут / Выговор лидеру","Пример: нельзя запросить и снайперские винтовки, и материалы, и эпинефрин одновременно."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('robbery', '3. Похищения — остальные правила', NULL, NULL, '["📌 3.3. Весь процесс похищения должен быть записан на видео. | Demorgan 15-35 минут всем участникам + Выговор лидеру","Примечание: видео хранить 72 часа, качество 720p, чёткий звук.","","📌 3.4. После получения выкупа за заложника, его необходимо отпустить в течение 5 минут. | Demorgan 35 минут всем участникам","Исключение: разрешено захватить с собой двух заложников, но их необходимо освободить до окончания зелёного коридора.","","📌 3.5. Запрещено брать переговорщика в заложники. | WARN","","📌 3.6. Запрещено совершать похищения в промежуток времени: с 02:00 до 10:00 МСК. | WARN","Исключение: похищение не несущее цели наживы (выкупа), а также похищение участников криминальных структур.","","📌 3.7. Каждая фракция/семья может совершить два похищения раз в 12 часов. | Demorgan 90 минут всем участникам / Выговор лидеру","Примечание: перерыв между похищениями — не менее 3 часов.","","📌 3.8. Выкупающая сторона имеет право 1 раз убедиться в целостности и количестве заложников.","Примечание: это обязательное условие, отказ = неадекватное требование.","","📌 3.9. Запрещено намеренно затягивать похищение. | Demorgan 35 минут всем участникам","Исключение: обсуждение условий выкупа до 5 минут не считается затягиванием.","","📌 3.10. Запрещено требовать выкуп менее чем за 15 минут.","","📌 3.11.1. Выкуп может осуществляться как сотрудниками LSPD/LSCSD/FIB, так и игроками криминальных структур/семей.","","📌 3.11.2. Информацию о похищении игрока из криминальной структуры/семьи он должен сообщить в /f или /c. | WARN / Ban 5-15 дней","","📌 3.11.3. Выкуп предоставляется согласно п.3.2.2-3.2.4. | Наказание согласно нарушенному пункту"]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('robbery', '4. Правила для жертвы', NULL, NULL, '["📌 4.1. Водителям авто запрещено продолжать движение, если дорога полностью перекрыта. | Demorgan 35 минут","","📌 4.2. Если по автомобилю открыли продолжительный огонь и грабителей значительно больше — водителю необходимо остановиться. | Demorgan 35 минут","","📌 4.3. Если похищен лидер/заместитель фракции/семьи либо министр City Hall — он обязан вести полную видеозапись с момента похищения. | Demorgan 90 минут / Выговор лидеру / Заморозка 5-15 дней","Примечание: видео хранить 72 часа, качество 720p, чёткий звук."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('robbery', '5. Правила выкупающей стороны (гос.структуры и криминал)', NULL, NULL, '["📌 5.1. Сторона выкупа обязана соблюдать все требования похитителей (выкуп, отход и т.д.). | Demorgan 90 минут / Выговор лидеру","Пояснение: разрешено требовать отмену патруля и зелёный коридор не более 45 секунд или в радиусе до 750 метров.","Исключение: жертве ничего не угрожает.","","📌 5.2.1. Разрешено начинать наступление только если жертве ничего не угрожает. | Demorgan 90 минут / Выговор лидеру","Исключение: по оцеплению/переговорщику открыт огонь.","","📌 5.2.2. Разрешено нападать, если требования похитителей неадекватны:","• Выкуп больше разрешённого правилами;","• Повторный запрос после выполнения;","• Запрос бронетехники/вертолёта;","• Нарушение условий зелёного коридора;","• Нарушение р.1 п.10;","• Нарушение р.3 п.2.1;","• Нарушение р.3 п.11.","","📌 5.2.3. Разрешено нападать, если переговорщика взяли в заложники или убили.","","📌 5.2.4. Запрещено начинать штурм, если у переговорщика и стороны захвата не состоялось диалога. | Demorgan 90 минут / Выговор лидеру","Исключение: по оцеплению/переговорщику открыт огонь, игнорирование переговорщика.","Примечание: преступной организации/семье запрещено игнорировать переговорщика. | Выговор лидеру","","📌 5.3. Разрешено объявлять похитителя в розыск после прямого контакта (встречи/диалога). | Demorgan 25 минут","Пояснение: если человек был без маски.","","📌 5.4. Сторона выкупа обязана уведомить сторону захвата об отправке переговорщика.","","📌 5.5. С момента первого вызова о заложниках у гос.структур есть 30 минут, чтобы среагировать. | Выговор лидеру FIB / Выговор лидерам LSCSD/LSPD при отсутствии лидера FIB","Примечание: если переговорщик не приезжает 30 минут — криминальной организации разрешено убивать 1 заложника раз в 5 минут."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('events', 'Ограбление банков — общие правила', NULL, NULL, '["1.1 Функциональное ограбление производится с 12:00 до 01:00.","1.2 Запрещено приезжать на ограбления, не имея при себе огнестрельного оружия. | Demorgan 15-35 минут.","1.3 Запрещено караулить грабителей на респаунах фракции/семей, а также на территории банка. | Demorgan 35 минут.","1.4 Запрещено покидать игру во время ограбления. | WARN / Ban 4-7 дней.","1.5 Игрокам, не находящимся в криминальной организации/семье, запрещено длительное время находиться поблизости к месту ограбления. | Demorgan 15-35 минут.","1.6 Запрещено использование услуг банка во время ограбления. | WARN / Ban 2 дня.","1.7 Запрещено перекрывать входы/выходы из банка транспортом. | Demorgan 35 минут.","1.8 Если ограбление банка происходит с участием заложника, то на данный процесс распространяются все правила похищений и ограблений. Исключение: р.3 п.9 правил ограблений и похищений не распространяется. Примечание: выкуп просить нельзя, только зелёный коридор для отхода (750 м, стремительно покинуть банк). | WARN.","1.9.1 Похищать человека на ограблении банка разрешено лишь в том случае, если он заранее находился в интерьере данного банка. | Demorgan 90 минут / Выговор лидеру.","1.9.2 В заложниках разрешено удерживать максимум 1 человека. | Demorgan 90 минут / Выговор лидеру. Примечание: запрещено продолжать ограбление, когда сторона выкупа выполнила все требования — необходимо оперативно покинуть банк."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('events', 'Ограбление банков — для криминальных организаций/семей', NULL, NULL, '["2.1 Разрешено нападать на банк в союзе (максимум 1 союз, между фракциями/семьями должен быть IC союз). | Demorgan 90 минут / Выговор лидеру.","2.2 Запрещено перехватывать/нападать на другую фракцию/семью. | Demorgan 30-90 минут / WARN / Выговор лидеру. Исключение: ответный огонь.","2.3 Подъезд к банку можно совершать на фракционном/семейном/личном транспорте, окрашенном в цвет фракции/семьи. | Demorgan 90 минут.","2.4 Разрешено вызывать подкрепление (IC путём). | Выговор лидеру."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('events', 'Ограбление банков — для государственных организаций', NULL, NULL, '["3.1 Оказывать помощь при ограблении банка может любая государственная силовая структура.","3.2 Разрешён штурм без каких-либо IC диалогов, если внутри нет заложников.","3.3 Разрешён IC диалог с целью переговоров с криминальной организацией."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('events', 'Ограбление бизнесов — общие правила', NULL, NULL, '["1.1 Ограбления бизнесов проводятся функционально с 12:00 до 01:00.","1.2 Разрешено использование любого огнестрельного оружия.","1.3 Запрещено приезжать на ограбления, не имея при себе огнестрельного оружия. | Demorgan 15-35 минут.","1.4 Запрещено караулить грабителей на респаунах фракции/семей, а также на территории бизнеса. | Demorgan 35 минут. Исключение: детективы.","1.5 Игрокам, не находящимся в криминальной организации/семье, запрещено длительное время находиться поблизости к месту ограбления. | Demorgan 15-60 минут. Исключение: заложник.","1.6 Запрещено перекрывать входы/выходы из бизнеса транспортом. | Demorgan 35 минут.","1.7 Если ограбление бизнеса происходит с участием заложника, то на процесс распространяются все правила похищения и ограбления (кроме р.3 п.9). Выкуп просить нельзя, только зелёный коридор (750 м). | WARN.","1.8 Подъезд к бизнесу на транспорте цвета фракции/семьи. | Demorgan 35 минут."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('events', 'Ограбление бизнесов — для криминала', NULL, NULL, '["2.1 Минимальное количество участников — 2. | Demorgan 15 минут всем участникам.","2.2 Если криминальные организации/семьи сталкиваются на территории одного бизнеса, они обязаны начать перестрелку. | Demorgan 35 минут / Выговор лидеру. Исключение: союзная дипломатия. Примечание: на игроков, грабящих бизнес, не распространяется правило PG о перестрелке 1x2 и т.п.","2.3 Разрешено нападать на бизнес в союзе (максимум 1 союз). | Demorgan 90 минут / Выговор лидеру.","2.4.1 Похищать человека на ограблении бизнеса разрешено, только если он заранее находился в интерьере бизнеса. | Demorgan 90 минут / Выговор лидеру.","2.4.2 В заложниках максимум 1 человек. | Demorgan 90 минут / Выговор лидеру.","2.4.3 Запрещено удержание заложника более 15 минут. | Demorgan 90 минут / Выговор лидеру."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('events', 'Террористические акты — общие положения', NULL, NULL, '["Цели теракта: нажива, революционный уклон (изменение законов/экономики), подрыв репутации госструктур, нарушение экономической стабильности.","1.1 Инициатор — только банда (при одобрении главного куратора фракции).","1.2.1 Теракты не чаще 1 раза в 3 дня (общий интервал).","1.2.2 После организации теракта на фракцию-организатора заморозка на 7 дней, союзные фракции — заморозка 7 дней.","1.3.1 Банда-организатор может привлечь союзную банду или семью.","1.3.3 Семья может поехать без банды-организатора (заморозка на банду и семью).","1.4 Максимум преступных организаций при акте — 3.","1.5 Минимум участников со стороны террора — 15 (возможны исключения).","1.6 Обязательно присутствие лидера организации-организатора (или двух заместителей).","1.7 Разрешено любое оружие и амуниция.","1.8 Для организации нужно одобрение гл.куратора/ГА. Форма: ник, кол-во участников и организации, план и путь отхода, требования.","1.9 Максимальные требования выкупа за одного заложника: 30 000$ + 3 эпинефрина.","1.10 При теракте работают все основные правила сервера.","1.11 Слив информации о теракте только через IC, данные на видеозаписи (хранить 48 часов, 480p, оригинальный звук). | Выговор лидеру.","1.12 Теракты, не указанные в правилах, по инициативе лидеров — при одобрении ГА/ПМ, с сохранением ограничений по времени."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('events', 'Террористические акты — правила для нападающей стороны (криминал)', NULL, NULL, '["2.1 У каждого агрессора должно быть огнестрельное оружие. | Demorgan 35 минут / Выговор лидеру.","2.2 Разрешено убивать заложника один раз в 7 минут. | Выговор лидеру. Исключение: штурм гос.игроков, невыполнение требований.","2.3 Запрещено брать переговорщика в заложники. | WARN / Выговор лидеру.","2.4 Запрещено намеренно затягивать похищение. | Demorgan 35 минут всем участникам / Выговор лидеру. Исключение: обсуждение условий до 5 минут.","2.5 Запрещено требовать выкуп менее чем за 15 минут. | Demorgan 35 минут всем участникам.","2.6 Запрещено унижать/издеваться, заставлять раздеваться, петь, танцевать. | Выговор лидеру.","2.7 Запрещено покидать зону теракта с заложником. | Выговор лидеру. Исключение: можно взять 2 заложников для предотвращения атаки, их оставить на пути отхода.","2.8 Выкупающая сторона имеет право 1 раз убедиться в целостности и кол-ве заложников.","2.9 Нападения разрешены с 17:00 до 22:00. | Выговор лидеру.","2.10 Запрещён уход на вражеский/союзный респавн фракции. | WARN + Выговор лидеру.","2.11 Запрещено похищать игроков и привозить их с собой на теракт.","2.12 Запрещено брать в заложники инициаторов теракта и союзников (всех участников)."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('events', 'Террористические акты — правила для государственных структур', NULL, NULL, '["3.1 На теракты и захваты зданий могут выезжать сотрудники всех силовых структур.","3.2 Запрещено использование спецсредств, не предусмотренных механикой сервера.","3.3.1 Сторона выкупа обязана соблюдать все требования похитителей (выкуп, отход, зелёный коридор до 45 сек или 750 м). | Demorgan 90 минут / Выговор лидеру. Исключение: жертве ничего не угрожает.","3.3.2 Переговорщиком — только старшие ранги фракции.","3.4.1 Запрещено подвергать жизнь заложников опасности. | WARN / Устный / Выговор лидеру. Исключение: неадекватные требования (выкуп сверх нормы, повторный запрос, запрос бронетехники, нарушение зелёного коридора, огонь по переговорщику).","3.4.2 Разрешено нападать, если переговорщика взяли в заложники или убили.","3.5 Разрешено преследовать агрессоров, перекрывать шоссе, патрулировать вне радиуса требований. | Выговор лидеру при нарушении.","3.6 Хотя бы одной силовой структуре необходимо отреагировать на теракт. | Выговоры всем лидерам силовых структур в случае игнорирования. Исключение: USSS, National Guard."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('events', 'Ограбление федерального реестра', NULL, NULL, '["RP мероприятие нацеленное на захват здания правительства (мэрии) с целью массового захвата заложников, взлома федерального реестра, изменения политического/экономического строя штата.","Взлом доступен 10 федеральных баз данных (каждая информация на сумму от 150 000$ до 250 000$).","Взлом через отыгровки /try у центрального компьютера. Длительность взлома всех баз — 10 минут. При первой попытке — глобальная сигнализация.","При успешном ограблении фракция получает 1 план ограбления и 1 ключ-карту Fleeca."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('events', 'Захват LSPD / LSCSD', NULL, NULL, '["Захват полицейского и шерифского департамента — RP мероприятие для подрыва авторитета гос.силовых структур и получения оружейного арсенала.","Взлом оружейного склада через /try. В департаментах 10 шкафчиков, на взлом каждого — 1 попытка.","Возможные предметы: технические, медицинские и оружейные материалы, Heavy Sniper, Heavy Sniper Mk2.","При захвате можно освободить заключённых из КПЗ через /try (1 человек — 1 попытка)."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('events', 'Захват офиса LS News', NULL, NULL, '["RP мероприятие: массовый захват заложников, подрыв репутации государства.","Атакующая сторона имеет право взять в заложники всех, кто находился в офисе.","Взлом главного компьютера (2 компьютера — 4 попытки /try). При удачном взломе — 1 раз использовать /wnews (посыл не оскорбительный, по правилам).","Также можно получить от 2 до 4 планов ограбления банка и от 2 до 4 ключ-карт Fleeca, а также технические материалы."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('events', 'Захват грузового поезда', NULL, NULL, '["RP мероприятие для получения ценных предметов.","Задача — захват движущегося по штату поезда. Нужно добраться до первого вагона с машинистом и наставить оружие.","Машинист нажимает тревогу (объявление в глобальный чат), сотрудники выдвигаются.","В течение 15 минут срезать петли с вагонов (на каждый вагон 2 попытки /try), затем вскрывать контейнеры.","Поезд перевозит военное снаряжение, амуницию, медикаменты, продовольствие. Выбор поезда — на усмотрение нападающих."]', NULL);
INSERT INTO info_items (section_id, title, number, description, items, who_applies) VALUES ('events', 'Захват городской газовой компании', NULL, NULL, '["Минимум 1 водный транспорт (желательно баржа).","После приближения лодки срабатывает сигнализация. Нужно подойти к резервуарам и открыть краник для выкачки (/try 2 попытки на каждый).","Выкачка ресурсов в лодку — 5 минут на резервуар.","Награда: нефть и газ, обмен на деньги или материалы на чёрном рынке."]', NULL);
